// Original learning scenarios. Source links are further reading, not copied exercises.
export type Difficulty = 'Starter' | 'Builder' | 'Professional';
export type Track = { id: string; title: string; stage: 'Foundation'|'Build'|'Operate'; description: string; topics: string[]; source: string };
export type Question = { id: string; track: string; title: string; prompt: string; options: string[]; answer: number; explanation: string; why: string[]; difficulty: Difficulty; source: string };
export type Guide = { id:string; track:string; title:string; body:string; example:string; source:string; tags:string[] };
export type Decision = { prompt:string; options:string[]; answer:number; explanation:string; why:string[] };
export type Incident = { id:string; title:string; track:string; difficulty:Difficulty; summary:string; logs:string[]; steps:Decision[]; source:string };
export type Project = { id:string; title:string; summary:string; level:string; steps:string[]; deliverable:string; source:string };
