// Authored choices put the correct answer first; a deterministic rotation varies its UI position.
function q(track:TrackId,n:number,title:string,prompt:string,options:string[],why:string[],explanation:string,difficulty:Difficulty='Builder',source=sources[track]):Question {
  const offset=(n+Object.keys(sources).indexOf(track))%options.length;
  return {id:`${track}-${n}`,track,title,prompt,options:[...options.slice(offset),...options.slice(0,offset)],answer:(options.length-offset)%options.length,why:[...why.slice(offset),...why.slice(0,offset)],explanation,difficulty,source};
}
export const questions: Question[] = [
  q('sql',1,'The missing deliveries','A deliveries table has 10 rows. Three rows have delivered_at = NULL. What does COUNT(delivered_at) return?',
    ['7','10','3','NULL'],['COUNT(expression) counts only non-NULL expression values.','COUNT(*) would count all 10 rows.','Three is the number of missing timestamps, not populated timestamps.','COUNT returns a number, including zero when nothing is counted.'],
    'Use COUNT(*) for rows and COUNT(delivered_at) for known delivery timestamps. Their difference is the missing-timestamp count. A NULL is unknown, not an empty string.','Starter','https://www.postgresql.org/docs/current/functions-aggregate.html'),
  q('sql',2,'Keep the customers with no orders','You need every customer, including those with no paid orders. Which join placement preserves them?',
    ["LEFT JOIN orders o ON c.id=o.customer_id AND o.status='paid'","LEFT JOIN orders o ON c.id=o.customer_id WHERE o.status='paid'",'INNER JOIN orders o ON c.id=o.customer_id','CROSS JOIN orders'],
    ['The ON condition restricts matches while preserving unmatched left rows.','The WHERE condition rejects NULL-extended rows, removing customers with no paid match.','An inner join omits customers with no matching order.','A cross join creates all combinations and does not express the relationship.'],
    'Outer joins preserve unmatched rows before WHERE runs. A filter on the right-hand table in WHERE can accidentally remove the very rows you intended to keep.','Starter','https://www.postgresql.org/docs/current/queries-table-expressions.html'),
  q('sql',3,'A total that doubled','An order has 2 line items and 3 payment attempts. Joining both child tables directly to the order produces how many rows for that order?',
    ['6','5','3','2'],['Each of the 2 items matches each of the 3 attempts: 2 × 3.','A join combines matching rows; it does not add the child counts.','Three ignores the two matching item rows per attempt.','Two ignores the three matching attempts per item.'],
    'This is join fanout. Aggregate each child to order grain before joining when you need one row per order; otherwise revenue can be multiplied.','Builder','https://www.postgresql.org/docs/current/queries-table-expressions.html'),
  q('sql',4,'One winner, even in a tie','In PostgreSQL, select exactly one latest event per device. Two events can share event_time. What makes ROW_NUMBER deterministic?',
    ['ORDER BY event_time DESC, event_id DESC using a unique event_id','ORDER BY event_time DESC only','Use RANK and filter rank = 1','Remove PARTITION BY'],
    ['The unique tie-breaker defines a complete order within each device.','Tied timestamps leave the selected row unspecified.','RANK returns multiple first-place rows when the ordering values tie.','Without partitioning, you pick one event for the entire result.'],
    'ROW_NUMBER selects one row per partition, but the ordering must express the business rule and break ties. “Latest” needs an explicit tie policy.','Builder','https://www.postgresql.org/docs/current/tutorial-window.html'),
  q('sql',5,'A surprising NOT IN','In PostgreSQL, excluded_ids contains (7, NULL). Why can WHERE customer_id NOT IN (SELECT id FROM excluded_ids) remove every row?',
    ['The NULL can make the predicate unknown for nonmatching IDs','NOT IN always acts like an inner join','NULL equals every customer ID','The optimizer deletes all rows'],
    ['An unknown comparison prevents the NOT IN predicate from being true.','NOT IN is a predicate, not an unconditional inner join.','NULL equality is unknown, not universally true.','SELECT filtering does not delete stored data.'],
    'Use a correlated NOT EXISTS for an anti-join, or exclude NULLs from the subquery when that matches the intended semantics. Include a NULL fixture in tests.','Professional','https://www.postgresql.org/docs/current/functions-subquery.html'),
  q('sql',6,'A query plan is evidence','A PostgreSQL query slowed after the table grew. What is the most useful first investigation?',
    ['Inspect its plan and measured row counts, safely using EXPLAIN ANALYZE when execution is acceptable','Add an index to every column','Assume every sequential scan is a bug','Increase a timeout and call it fixed'],
    ['Plan operators, estimates, actual rows, and timing narrow the bottleneck.','Indexes cost storage and writes and may not match the predicates.','A sequential scan can be efficient when many rows are needed.','A longer wait does not identify or resolve the cause.'],
    'Compare estimated and actual cardinalities, scan filters, join strategy, and sort work. EXPLAIN ANALYZE executes the statement, so treat modifying statements with care.','Professional','https://www.postgresql.org/docs/current/using-explain.html'),

  q('python',1,'Read a file larger than RAM','A Python job transforms a 20 GB newline-delimited JSON file on a 2 GB worker. Which approach bounds input memory?',
    ['Iterate over the file and process bounded batches','Read the whole file with read()','Wrap list(file) around the iterator','Load every decoded object into a list'],
    ['Streaming lines with a bounded batch avoids retaining the full input.','read() attempts to load the full contents.','list(file) materializes all lines.','Keeping all decoded objects defeats streaming and adds object overhead.'],
    'An iterator is only memory-efficient when downstream code also avoids accumulating everything. Bound batch sizes and flush output regularly.','Starter','https://docs.python.org/3/tutorial/inputoutput.html'),
  q('python',2,'Money without binary rounding surprises','A payment feed sends prices as strings such as "19.99". Which Python representation best preserves decimal intent?',
    ['Decimal("19.99") with an explicit rounding policy','float("19.99") and assume exact arithmetic','Decimal(19.99)','Round every intermediate calculation to an integer'],
    ['Parsing the original string avoids importing a binary floating-point approximation.','Many decimal fractions have no exact binary float representation.','Constructing from a float preserves its binary approximation.','Integer rounding discards cents and can compound errors.'],
    'Use Decimal from the source string or integer minor units with a currency scale. Decide where rounding happens and document the rounding mode.','Starter','https://docs.python.org/3/library/decimal.html'),
  q('python',3,'The half-written export','A local export must never replace the last good file with incomplete output. What is the strongest ordinary filesystem pattern?',
    ['Write a temporary file on the same filesystem, flush/close it, then replace the destination','Open the final path and overwrite it immediately','Delete the old file before processing','Catch all errors and pretend the write succeeded'],
    ['A completed temporary file can be atomically replaced where filesystem semantics support it.','Readers may see partial content or lose the last good version.','Failure after deletion leaves no valid export.','Suppressing errors hides missing or corrupted output.'],
    'Atomic replacement protects visibility; crash durability may additionally require fsync of file and directory. Object stores need their own publish/commit strategy.','Builder','https://docs.python.org/3/library/os.html#os.replace'),
  q('python',4,'Retry the right failure','A fetch receives HTTP 429 with Retry-After. Which behavior is appropriate?',
    ['Wait according to the server guidance and retry with a bounded policy','Retry continuously without delay','Treat it as a successful empty dataset','Retry forever, including invalid credentials'],
    ['A bounded, delayed retry respects throttling and limits runaway work.','A tight loop increases load and may worsen throttling.','An empty result silently corrupts completeness expectations.','Permanent failures require intervention, and unbounded retries hide them.'],
    'Classify retryable failures, set timeouts and attempt limits, honor Retry-After, and add jitter where appropriate. Preserve the checkpoint until the page is durable.','Builder','https://www.rfc-editor.org/rfc/rfc6585#section-4'),
  q('python',5,'A daylight-saving collision','Two local timestamps both say 01:30 during a daylight-saving fall-back. What information prevents ambiguous ordering?',
    ['An aware timestamp carrying the UTC offset or a resolved timezone and fold','The local clock string alone','The server’s current timezone','Sorting the formatted clock strings'],
    ['Offset-aware instants distinguish the repeated local hour.','The same local clock value can represent two different instants.','The runtime timezone does not recover the source instant.','String order cannot resolve missing temporal information.'],
    'Normalize instants to UTC for ordering and retain the original zone for business reporting. Never silently attach a guessed timezone to ambiguous data.','Professional','https://docs.python.org/3/library/datetime.html'),
  q('python',6,'Validate the parser, not just the happy path','A CSV parser works on one neat example. Which test set gives the most useful additional coverage?',
    ['Quoted delimiters, embedded newlines, empty fields, Unicode, malformed records, and a known expected result','The same row repeated 100 times','Only a file-exists assertion','A test that copies the parser’s algorithm into the expected-value function'],
    ['These cases probe format boundaries and explicit failure behavior.','Repetition tests volume weakly but misses structural edge cases.','File existence says nothing about parsed values.','Duplicating the implementation can duplicate its bugs.'],
    'Use the csv module and small independently specified fixtures. Test what the pipeline must do with bad rows: reject, quarantine, or fail the batch.','Professional','https://docs.python.org/3/library/csv.html'),

  q('modeling',1,'Declare the grain first','You are designing sales facts. Which statement is a useful grain declaration?',
    ['One row per purchased order line','The table contains sales data','The table has lots of dimensions','One row per customer, order, product, and month depending on the source'],
    ['It states exactly what one row represents.','A subject area does not define row-level meaning.','A count of dimensions does not establish grain.','Mixing grains makes aggregations ambiguous.'],
    'Choose the business event represented by a row before choosing measures. Quantity and line revenue fit order-line grain; customer lifetime value does not naturally belong on every line.','Starter'),
  q('modeling',2,'Balances across time','A daily bank-account snapshot stores ending_balance. Which aggregation is usually meaningful?',
    ['Sum across accounts for one snapshot date','Sum the same account’s daily balances to get its month-end balance','Average account IDs','Sum across every dimension without qualification'],
    ['Balances are additive across compatible accounts at the same point in time.','Summing snapshots over time counts the same money repeatedly.','Identifiers are labels, not numeric measures.','A balance is commonly semi-additive, so the time dimension needs special handling.'],
    'Separate additive measures such as transaction amounts from semi-additive snapshots and non-additive ratios. The aggregation rule belongs in the metric definition.','Starter'),
  q('modeling',3,'Preserve the old address','A customer moves in June. Reports must show the address valid at each historical sale. Which dimension strategy fits?',
    ['Type 2 history with effective intervals and a surrogate key per version','Overwrite the existing address only','Store only the latest address in each report','Join facts to every version by customer ID alone'],
    ['Each historical version has a validity interval that can resolve the fact-time relationship.','Overwriting loses the old value needed for historical reporting.','The latest address rewrites historical attribution.','Joining all versions creates duplicates and incorrect attribution.'],
    'Use nonoverlapping effective intervals and a well-defined boundary convention, such as start inclusive and end exclusive. Resolve each fact to the correct version.','Builder'),
  q('modeling',4,'A ratio that cannot be averaged','Store A has 1 return out of 2 sales. Store B has 10 returns out of 100 sales. What is the combined return rate?',
    ['11 / 102, about 10.8%','The simple average of 50% and 10%, which is 30%','60%','11% exactly'],
    ['Add numerators and denominators, then divide.','An unweighted average treats the stores as equally sized.','Adding rates has no valid denominator.','The denominator is 102, not 100.'],
    'Persist or expose the additive components of ratios. The overall rate is SUM(returns) / SUM(sales), with an explicit zero-denominator policy.','Builder'),
  q('modeling',5,'One passenger, several loyalty programs','A passenger can belong to multiple loyalty programs. A fact-to-program join inflates trip revenue. What should the model specify?',
    ['A many-to-many bridge plus an explicit allocation or distinct-at-grain reporting rule','A random program per passenger with no documented rule','Duplicating full revenue to each program and summing it as total revenue','Removing the trip identifier'],
    ['The bridge expresses membership; the metric rule prevents accidental double counting.','Random attribution changes results and lacks business meaning.','Full attribution may be intentional for some views, but is not additive across programs.','Removing grain keys makes duplicate detection harder.'],
    'Many-to-many relationships require a deliberate business definition. Equal weighting is one possible policy, not an automatic truth.','Professional'),
  q('modeling',6,'Late dimension, early fact','A sale arrives before its customer profile. You must preserve the sale and repair attribution later. Which approach fits?',
    ['Use an inferred/unknown member with a repair path and monitor unresolved keys','Discard the sale permanently','Assign a random existing customer','Delay every warehouse table indefinitely'],
    ['It preserves the event while acknowledging temporarily incomplete context.','Discarding the event loses valid business activity.','Invented attribution is worse than an explicit unknown.','A local data delay need not halt unrelated domains.'],
    'Track the natural key and unresolved state so late dimension data can repair the relationship. Make the unknown-member policy visible to consumers.','Professional'),

  q('ingestion',1,'Checkpoint after durability','An API page has been fetched but its records have not yet been stored. When should the durable cursor advance?',
    ['After the page’s records are durably committed under a replay-safe design','Immediately after receiving the HTTP response','Before sending the request','Only after the entire year has been ingested'],
    ['A committed page can safely establish the next restart position.','A crash before storage would skip records after restart.','Advancing before reading can skip an unread page.','Very infrequent checkpoints cause unnecessarily large replays.'],
    'Coordinate output and checkpointing. If atomic coordination is unavailable, prefer a possible replay with deduplication over silently skipping data.','Starter'),
  q('ingestion',2,'Deletion without an updated timestamp','A source hard-deletes orders. A daily extractor only selects rows with updated_at after yesterday. What is missing?',
    ['A delete capture mechanism, such as a change log or reconciliation','A wider SELECT list','More decimal precision','A LIMIT clause'],
    ['Deleted rows no longer exist to satisfy the timestamp filter.','Selecting more columns cannot retrieve an absent row.','Numeric precision is unrelated to deletion detection.','A limit may omit more data, not restore deleted records.'],
    'Incremental timestamp extraction needs an explicit deletion strategy. CDC delete events, source tombstones, soft deletes, or periodic reconciliation can each fit different systems.','Starter'),
  q('ingestion',3,'Equal watermark timestamps','An extractor uses WHERE updated_at > last_timestamp. Several rows share the final page’s timestamp. What prevents skipping tied rows?',
    ['A stable composite cursor such as (updated_at, primary_key), with matching ordering','Increase the page size and assume ties disappear','Store only the timestamp rounded to the hour','Order each page randomly'],
    ['The key breaks ties so the next cursor describes a precise position.','A larger page does not guarantee a tie never crosses a boundary.','Coarser timestamps increase ambiguity.','Random ordering makes stable pagination impossible.'],
    'For a mutable source, also account for updates during pagination and late timestamps. A composite cursor solves ordering ties, not every consistency problem.','Builder'),
  q('ingestion',4,'Snapshot meets live changes','A CDC bootstrap copies existing rows while new writes continue. What must the handoff establish?',
    ['A consistent relationship between snapshot contents and the change-log position','That the snapshot contains only the newest ten rows','That live changes are permanently ignored','That every source table has identical row counts'],
    ['The handoff must avoid gaps and make any replay duplicates manageable.','Sampling is not a complete bootstrap.','Ignoring changes makes the replica stale immediately.','Tables need not have equal size.'],
    'Use the connector’s documented snapshot/log coordination rather than inventing a wall-clock cutoff. Keep source offsets and operation types as evidence.','Builder'),
  q('ingestion',5,'An upstream type changed','A producer changes amount from integer cents to a currency string. What should a reliable ingestion boundary do?',
    ['Detect the contract violation, quarantine or fail according to policy, and alert with sample metadata','Silently coerce every unparseable value to zero','Drop the column without notifying consumers','Keep successful status regardless of rejected rows'],
    ['An explicit policy protects consumers and preserves evidence for repair.','Zero is a real value and hides data loss.','Removing the column breaks downstream meaning.','Success without a rejected-row policy conceals incomplete ingestion.'],
    'Schema compatibility includes meaning and units, not just storage types. Version contracts and coordinate migrations with consumers.','Professional'),
  q('ingestion',6,'Duplicate change events','A consumer restarts and sees the same CDC update twice. How should a current-state sink handle it?',
    ['Apply changes idempotently by business key and a source ordering/version rule','Append both as separate current rows','Deduplicate by processing timestamp alone','Ignore every update after the first insert'],
    ['A key and ordering rule make replays safe and reject stale updates where appropriate.','A current-state table should not gain two current copies of one entity.','Processing time changes on replay and does not identify the source event.','Ignoring updates freezes stale state.'],
    'An event-history table may retain duplicate deliveries separately from logical events. A current-state materialization needs explicit update and delete semantics.','Professional'),

  q('orchestration',1,'Safe to run twice','A daily task may be retried after a worker crash. Which write pattern is most suitable?',
    ['Replace or merge the intended partition using stable keys','Append the same rows again on every attempt','Use the current clock to choose a new output partition each retry','Mark success before writing'],
    ['The same logical run converges to the same intended result.','An append-only retry can duplicate data.','A moving output target makes retries nondeterministic.','Success before durable output risks silent loss.'],
    'Idempotence is about the observable result of repeating an operation. It requires a write strategy and stable inputs, not merely a retry setting.','Starter'),
  q('orchestration',2,'Run the date you meant','An Airflow run is backfilling a day from last month. Which value should define its data selection?',
    ['The run’s intended data interval','The worker’s current date','The latest file regardless of its date','The time when the UI button was clicked'],
    ['The data interval expresses the logical slice being processed.','The current date would process today instead of the historical slice.','Latest-file selection makes backfills unstable.','Click time does not define the historical input partition.'],
    'Separate logical data time from execution time. This makes scheduled runs, retries, and backfills reproducible.','Starter'),
  q('orchestration',3,'An expensive DAG import','A DAG file queries a large database at module import. Why is this risky?',
    ['The scheduler parses DAG files repeatedly, so import-time work adds latency and load','Python imports cannot contain functions','The database will automatically cache all queries forever','It guarantees exactly-once execution'],
    ['Repeated parsing should be lightweight and free of unnecessary external work.','Functions are normal in Python modules.','Database caching is not a guarantee and does not remove all cost.','Import side effects are not task execution guarantees.'],
    'Move heavy I/O and computation into tasks. Keep DAG construction quick and deterministic so scheduling remains responsive.','Builder'),
  q('orchestration',4,'Passing a huge dataset between tasks','Task A produces 8 GB of transformed data for task B. What should it pass through orchestration metadata?',
    ['A durable object/table reference plus relevant partition and checksum metadata','The whole dataset as an ordinary XCom value','A path on an ephemeral worker’s private disk with no shared storage','Only the string "done"'],
    ['The next task can retrieve durable data without bloating the metadata store.','Large payloads overload a channel designed for coordination unless a suitable backend is explicitly configured.','The next task may run on a different worker or after the disk disappears.','A bare success word does not locate or identify the output.'],
    'Use object storage or a database for bulk data and orchestration messages for references. Make ownership, format, and retention explicit.','Builder'),
  q('orchestration',5,'A backfill overwhelms production','Launching 365 historical daily runs saturates the warehouse. What is the best control?',
    ['Bound concurrency with pools/run limits and schedule the backfill against capacity','Increase retries to 100','Remove every dependency','Run all partitions in parallel because historical data is free'],
    ['Concurrency controls preserve capacity for live workloads.','More retries can intensify overload.','Removing dependencies can produce incorrect results.','Historical processing uses the same finite compute and I/O resources.'],
    'Backfills are production workloads. Estimate volume, isolate resources when possible, and monitor live freshness while historical partitions catch up.','Professional'),
  q('orchestration',6,'A failed task that already sent an email','A task writes data and sends a notification, then fails. Retrying can send duplicate emails. What design reduces this risk?',
    ['Separate durable completion from notification and use a deduplication/outbox key','Assume orchestration retries undo the email','Disable every retry across the pipeline','Hide the failure and mark the task successful'],
    ['A durable event keyed by logical completion can coordinate repeat-safe delivery.','External side effects are not automatically rolled back.','Disabling all retries sacrifices recovery without solving the side-effect contract.','False success hides uncertain output.'],
    'Treat side effects separately from pure transformation. Exactly-once notification needs cooperation from the delivery system or an explicit deduplication mechanism.','Professional'),

  q('quality',1,'What a data test returns','In a dbt singular data test, what does the SQL typically return?',
    ['Rows that violate the asserted rule','All correct rows only','A mandatory Boolean named success','A new production table that overwrites the model'],
    ['Failing rows provide evidence of the violated assertion.','Returning correct rows would invert the usual test convention.','A Boolean result is not the standard failing-row pattern.','Tests validate data; they do not replace the model by default.'],
    'For a nonnegative amount rule, select rows where amount < 0. Zero failing rows means the assertion passed for the tested data.','Starter'),
  q('quality',2,'Unique is not complete','An order_id column passes a uniqueness test. Does that establish that every order has an ID?',
    ['No; use a separate non-null assertion as well','Yes; unique automatically means non-null in every system','Yes, if IDs are integers','Only when the table is large'],
    ['Uniqueness and missingness are distinct properties.','NULL handling varies, and dbt exposes separate assertions.','Integer type does not prevent NULL unless constrained.','Table size does not change the logical requirement.'],
    'A usable key usually needs both uniqueness and non-nullness. Referential integrity and business completeness need additional tests.','Starter'),
  q('quality',3,'Test transformation logic before production','A model classifies late shipments. You want to check boundary cases with fixed mock inputs before loading a warehouse. Which test fits?',
    ['A unit test with explicit input and expected output rows','Only a source freshness check','Only a row-count dashboard','A screenshot of the SQL'],
    ['A unit test isolates the transformation logic on controlled examples.','Freshness says when data arrived, not whether classification is correct.','A count may stay constant while every classification is wrong.','A screenshot provides no executable assertion.'],
    'Use unit tests for logic such as exactly-at-deadline behavior, NULL times, and timezone boundaries. Use data tests to check properties of materialized data.','Builder','https://docs.getdbt.com/docs/build/unit-tests'),
  q('quality',4,'Late updates in an incremental model','A model selects only rows newer than the maximum loaded event_time. A correction arrives for an older event. What should the design consider?',
    ['A replay/lookback or source-change-based strategy with a stable merge key','Assume old events never change','Use a larger warehouse and keep the same incorrect filter','Remove all tests'],
    ['The strategy must revisit changed historical rows and merge them correctly.','The scenario explicitly includes a historical correction.','More compute cannot recover rows excluded by logic.','Removing tests makes stale results harder to detect.'],
    'Incremental correctness depends on the source’s mutation and lateness behavior. A lookback is bounded protection, not a guarantee for arbitrarily late changes.','Builder','https://docs.getdbt.com/docs/build/incremental-models'),
  q('quality',5,'Fresh but incomplete','The latest loaded timestamp is one minute old, but a source partition is missing. Which statement is correct?',
    ['Freshness alone does not prove completeness; reconcile expected partitions or source counts','The dataset is complete because its newest row is recent','A non-null test will find every missing row','The problem can be fixed by renaming the table'],
    ['Recency and coverage measure different failure modes.','One recent record can coexist with a large data gap.','A test on present rows cannot necessarily detect absent rows.','A name change does not restore missing input.'],
    'Combine freshness, completeness, validity, and reconciliation checks. Define what should have arrived so absence becomes observable.','Professional','https://docs.getdbt.com/docs/deploy/source-freshness'),
  q('quality',6,'A schema contract passed, but money is wrong','An amount column keeps its numeric type but changes from dollars to cents. Why can a schema-only contract miss it?',
    ['The physical type is unchanged while the business unit changed','Numeric types automatically carry all currency units','Contracts always compare to a bank statement','A column rename is the only possible breaking change'],
    ['Meaning and units need semantic documentation and checks beyond type validation.','Most numeric columns do not encode a business unit in their type.','External reconciliation must be explicitly implemented.','Meaning, cardinality, and nullability changes can also break consumers.'],
    'Document units and ownership, use representative value checks and reconciliations, and require review of semantic changes. A type contract is one layer of protection.','Professional','https://docs.getdbt.com/docs/mesh/govern/model-contracts'),

  q('spark',1,'Why the network gets busy','A Spark GROUP BY customer_id aggregates data spread across many partitions. Why might it require a shuffle?',
    ['Rows for the same key must meet across partition boundaries','Every SELECT statement always downloads the entire internet','A shuffle is only a user-interface refresh','Grouping automatically requires a single physical machine'],
    ['Data is redistributed so keyed aggregation can combine matching records.','Network work depends on the plan and data sources.','Shuffle is an execution data exchange.','Groups can be distributed across many workers after repartitioning.'],
    'Exchanges move data, often involving network and disk. Inspect the physical plan and shuffle metrics before choosing an optimization.','Starter'),
  q('spark',2,'Read only what you need','A wide Parquet table has 200 columns; the report needs 3 and one date range. What is a useful first optimization?',
    ['Project needed columns and apply supported filters early','Convert everything to strings first','Collect the entire table to the driver','Read every column to be safe'],
    ['Column pruning and applicable filter pushdown can reduce I/O.','String conversion can inhibit efficient typed processing.','Collecting a large table risks driver memory failure.','Unused columns increase reading and decoding work.'],
    'Confirm the executed plan actually prunes columns and partitions. The benefit depends on storage layout, statistics, and predicate support.','Starter'),
  q('spark',3,'The tiny lookup table','A 5 MB country lookup joins a large fact table. Which strategy may avoid shuffling the large side?',
    ['Broadcast the small side if it safely fits executor memory and the join supports it','Broadcast the entire fact table','Always repartition to one partition','Sort the lookup alphabetically in a spreadsheet'],
    ['Each executor can use a local copy of the small lookup.','A huge broadcast risks memory and network pressure.','One partition removes parallelism and can overload one task.','Spreadsheet order does not determine Spark’s distributed join strategy.'],
    'Use actual size estimates and inspect the chosen plan. A broadcast hint is not a license to ignore memory limits or unsupported join types.','Builder'),
  q('spark',4,'One task lasts forty minutes','Most join tasks finish in 20 seconds; one hot customer key contains half the input. What is the likely issue?',
    ['Key skew concentrating work in a small number of partitions','Every executor needs the same larger timeout','The job has too many column names','A single typo in the dashboard title'],
    ['Uneven key frequencies can create a straggler partition.','A timeout change does not rebalance skewed data.','Column names do not explain the extreme partition imbalance.','A presentation typo does not cause distributed execution skew.'],
    'Check partition sizes and task metrics. Possible remedies include adaptive skew handling, pre-aggregation, or carefully designed salting; choose from evidence.','Builder'),
  q('spark',5,'Caching with a purpose','A DataFrame is used once, then discarded. What is the best default view of caching it?',
    ['It may add materialization and memory cost without reuse benefit','Caching always makes every job faster','Caching guarantees source freshness forever','Caching replaces the need for a correct join'],
    ['Caching pays off when saved recomputation outweighs storage and management costs.','Not all workloads benefit, especially single-use data.','Cached results can be stale relative to changing sources.','Execution reuse does not fix relational logic.'],
    'Cache selectively around expensive reused results, measure the benefit, and unpersist when no longer needed. Include memory pressure in the decision.','Professional'),
  q('spark',6,'Too many tiny output files','A streaming-to-batch pipeline writes thousands of tiny Parquet files per partition. Why might compaction help?',
    ['It reduces per-file planning and I/O overhead, with a target size chosen for the workload','It changes incorrect values into correct ones automatically','It eliminates every future shuffle','It guarantees zero cloud cost'],
    ['Many small files create overhead disproportionate to their data volume.','Compaction rearranges storage; it does not infer correct business values.','Downstream joins and aggregations may still shuffle.','Compaction itself consumes resources and storage operations.'],
    'Avoid both file extremes. Tiny files burden metadata and reads; excessively large files can reduce parallelism or worsen rewrite costs.','Professional'),

  q('streaming',1,'When did it really happen?','A bus sensor records an event at 09:00 but reconnects at 09:07. Which timestamp is event time?',
    ['09:00, the timestamp of the observed event','09:07, when the processor receives it','The time the dashboard is opened','The next checkpoint time'],
    ['Event time represents when the underlying event occurred.','Arrival/processing time reflects the system handling the event.','Viewing time is unrelated to the source event.','Checkpoint time concerns state recovery.'],
    'Use event time for business windows when source timestamps are meaningful. Delayed arrivals require an explicit lateness and correction policy.','Starter'),
  q('streaming',2,'A watermark is not a wall clock','What does an event-time watermark help a streaming operator decide?',
    ['How far event-time progress has advanced for deciding when to complete windows','The exact current UTC time on every producer','That no late event can ever arrive','How many CPU cores to buy'],
    ['Watermarks represent progress assumptions used by event-time operations.','They are not a clock synchronization protocol.','Late data can still arrive and needs handling.','Resource sizing is a different concern.'],
    'Watermark design trades result latency against tolerance of out-of-order data. Treat the lateness assumption as a measurable product policy.','Starter'),
  q('streaming',3,'The idle partition','One input partition has stopped producing data. A window never closes even though others advance. What should you investigate?',
    ['Whether the idle input holds back the combined watermark and needs appropriate idleness handling','Whether every event should be discarded','Whether SQL keywords are uppercase','Whether the dashboard should hide unfinished windows'],
    ['Combined progress can depend on the slowest active input.','Discarding all events loses useful data.','Keyword casing does not affect watermark progress.','Hiding the symptom does not define correct completion.'],
    'Inspect per-input watermarks and activity. Marking inputs idle must match source behavior; resumed late events still need a policy.','Builder'),
  q('streaming',4,'Exactly-once where?','Kafka transactions protect a read-process-write flow inside Kafka. The same task also calls an external payment API. What can you conclude?',
    ['The external side effect needs its own transactional or idempotent cooperation','Kafka transactions automatically roll back any HTTP call','Every payment will happen exactly once regardless of the API','Retries can be removed because failures are impossible'],
    ['End-to-end guarantees require all relevant boundaries to cooperate.','Kafka cannot automatically undo an arbitrary remote side effect.','The API’s behavior and deduplication determine payment safety.','Transactions do not eliminate failures.'],
    'State the scope of every delivery guarantee. Use a stable payment idempotency key or a coordinated design when an external system participates.','Builder','https://kafka.apache.org/41/design/design/'),
  q('streaming',5,'Backpressure after a sink slowdown','The database sink’s latency rises, queues grow, and upstream operators slow down. What is the most useful first response?',
    ['Inspect sink throughput, errors, batching, and capacity before adding arbitrary source parallelism','Double the source rate','Drop checkpointing to hide the latency','Increase all queue sizes forever'],
    ['Backpressure often propagates from the downstream bottleneck.','More input can amplify the backlog.','Removing recovery protection does not fix sink throughput.','Unbounded buffering eventually exhausts resources.'],
    'Measure arrival rate versus sustainable service rate. Apply bounded buffering and controlled flow while addressing the slow component.','Professional','https://nightlies.apache.org/flink/flink-docs-stable/docs/ops/monitoring/back_pressure/'),
  q('streaming',6,'State that never expires','A deduplication operator remembers every event ID forever. What risk grows with an unbounded stream?',
    ['Unbounded state and increasingly costly recovery unless retention is designed','The IDs automatically become unique after a day','The stream turns into a static table','Watermarks automatically delete every kind of user state'],
    ['State needs an explicit retention and correctness contract.','Time passing does not change duplicate identity.','New events keep arriving.','Cleanup depends on the API, timers, TTL, and operator design.'],
    'Choose a deduplication horizon from replay and lateness requirements. Expiring state means duplicates beyond that horizon may no longer be recognized.','Professional','https://nightlies.apache.org/flink/flink-docs-stable/docs/dev/datastream/fault-tolerance/state/'),

  q('lakehouse',1,'Columnar storage for analytics','A report reads 4 columns from a 100-column table. Why can Parquet be a good fit?',
    ['Columnar layout can avoid reading and decoding many unused columns','It guarantees every query has no I/O','It encrypts every column by default in every setup','It replaces the need for a table schema'],
    ['Analytical projections can benefit from column-oriented storage.','Queries still need relevant data and metadata.','Encryption requires the relevant format and system configuration.','A structured format still has schema information and compatibility concerns.'],
    'Storage format and table format solve different problems. Parquet organizes columnar files; a table format coordinates a collection of files and metadata.','Starter','https://parquet.apache.org/docs/overview/'),
  q('lakehouse',2,'Files are not a transaction log','Why add a table format such as Iceberg on top of object storage?',
    ['To manage table metadata, snapshots, schema evolution, and coordinated commits','To make every object-store request free','To remove all need for a query engine','To guarantee that every consumer uses the same business metric'],
    ['A table abstraction coordinates files into consistent table states.','Storage and request costs still exist.','An engine is still needed to execute queries.','Metric governance remains an application and modeling responsibility.'],
    'A bucket of files needs conventions for readers and writers. Table metadata supplies capabilities that raw directory listings alone do not provide.','Starter','https://iceberg.apache.org/docs/latest/reliability/'),
  q('lakehouse',3,'Change the partition strategy','An Iceberg table moves from daily to hourly partitioning. What does partition evolution allow?',
    ['New data can use the new specification while readers handle data written under older specifications','Every historical file must immediately be renamed by hand','Old data becomes unreadable by definition','Partitioning changes the business timestamp values'],
    ['Metadata tracks multiple partition specifications.','Evolution avoids requiring an immediate manual rewrite of all historical files.','Supported readers resolve the table’s metadata.','Partition transforms organize data without redefining its source values.'],
    'Changing a specification does not automatically optimize old files. Rewrite historical data separately when its performance benefit justifies the cost.','Builder'),
  q('lakehouse',4,'Rename a column safely','Why does Iceberg track fields with IDs rather than relying only on position or name?',
    ['Stable identity helps distinguish renames and evolution from unrelated fields','IDs make all strings shorter','Column order never appears in any file format','Names are prohibited in SQL'],
    ['Field identity prevents accidental reinterpretation when schemas evolve.','Identity metadata is not primarily string compression.','Physical representations can still have ordering.','SQL uses names; internal IDs preserve schema meaning.'],
    'A drop and a later add with the same name must not silently reuse old data as though it were the same field. Follow supported evolution operations.','Builder'),
  q('lakehouse',5,'A cleanup job broke a long query','A maintenance job deletes data files still referenced by a snapshot used by a reader. What was missing?',
    ['Retention and deletion rules that respect active/reachable snapshots and reader requirements','A prettier filename','More SQL aliases','A random delay of one second'],
    ['Physical deletion must respect the table’s reference and retention semantics.','Names do not establish reachability or safety.','Aliases do not protect storage files.','An arbitrary delay does not prove all readers are finished.'],
    'Use table-aware maintenance procedures and a retention window matched to query duration, rollback, and recovery needs. Avoid ad hoc deletion of table files.','Professional','https://iceberg.apache.org/docs/latest/maintenance/'),
  q('lakehouse',6,'Time travel is not an unlimited backup','A team relies only on table snapshots for disaster recovery. What limitation should they recognize?',
    ['Expired snapshots, deleted files, or loss of the storage/catalog can remove recovery paths','Snapshots always survive deletion of the entire storage account','Every table keeps all snapshots forever','Time travel makes restore tests unnecessary'],
    ['Snapshot availability depends on retention and the underlying metadata and data.','Table metadata cannot recover physically lost data without another copy.','Retention policies commonly remove historical states.','Recovery assumptions still need testing.'],
    'Define separate retention, backup, replication, and restore procedures from your recovery objectives. Time travel is useful but not a universal disaster-recovery strategy.','Professional','https://iceberg.apache.org/docs/latest/maintenance/'),

  q('cloud',1,'A loader with too much power','A daily loader only reads one source prefix and writes one target prefix. What permission scope is appropriate?',
    ['Only the required actions on those resources, with relevant conditions','Administrator access because it is easier','Public write access on the whole bucket','Every permission used by any other team'],
    ['Least privilege limits the impact of bugs or compromised credentials.','Administrator rights greatly exceed the task’s needs.','Public writes expose the dataset to untrusted changes.','Unrelated permissions create unnecessary access paths.'],
    'Start from required operations, resource names, and conditions. Review actual usage and separate production roles from development.','Starter'),
  q('cloud',2,'Where does the API key belong?','A mobile web app needs a paid model API. Where should the provider secret live?',
    ['In a server-side secret store, accessed by an authenticated backend','In the JavaScript bundle','In a public Git repository with an obscure filename','In a hidden HTML input'],
    ['The backend can protect the secret and enforce authorization and quotas.','Users can inspect bundled client code.','Obscurity does not prevent secret discovery.','Hidden fields remain readable in the browser.'],
    'Client applications cannot keep a shared provider secret confidential. Restrict backend actions, rotate secrets, and avoid logging their values.','Starter','https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html'),
  q('cloud',3,'Encryption is not authorization','A bucket is encrypted at rest but readable by everyone. Is its personal data protected from public readers?',
    ['No; authorized storage access can decrypt data, so access policy still matters','Yes; encryption means nobody can read it','Yes, if the filenames are random','Only CSV data can leak'],
    ['Encryption and access control address different threats.','The service decrypts data for permitted requests.','Random names are not a substitute for access control.','Any supported file format can expose sensitive contents.'],
    'Use least privilege, encryption in transit and at rest, audit logs, and data minimization together. Verify effective permissions rather than relying on a single checkbox.','Builder'),
  q('cloud',4,'A query budget that explains itself','Warehouse spend doubled. Which evidence best helps identify the cause?',
    ['Per-workload usage tags, query history, scanned bytes/runtime, and recent workload changes','The dashboard’s accent color','Only the total monthly invoice','The number of developers’ laptops'],
    ['Attribution connects resource use to specific jobs and changes.','Visual styling does not explain compute usage.','A total establishes the symptom but not which workload caused it.','Laptop count is not direct evidence of warehouse consumption.'],
    'Track cost per useful unit, such as a refreshed partition or million events, alongside total spend. Optimize the expensive path without silently reducing correctness.','Builder','https://docs.aws.amazon.com/wellarchitected/latest/cost-optimization-pillar/welcome.html'),
  q('cloud',5,'A useful log that leaks PII','A parser logs entire rejected customer rows, including addresses and tokens. What is a better pattern?',
    ['Log redacted identifiers and error categories; store restricted quarantine data only when needed','Keep every secret in logs for convenience','Publish rejected rows to a public issue','Turn off all monitoring forever'],
    ['It preserves diagnostic value while limiting sensitive exposure.','Logs are often widely accessible and retained for long periods.','Public issues disclose personal or secret data.','No monitoring makes failures opaque; safer telemetry is possible.'],
    'Treat logs as a data product with access, retention, and redaction rules. Avoid collecting sensitive fields that do not help resolve the error.','Professional','https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html'),
  q('cloud',6,'Cross-tenant data isolation','A user submits another tenant’s dataset ID to an API. What must prevent access?',
    ['Server-side authorization that checks the resource’s tenant against the authenticated identity','Hiding the dataset ID in the UI','A disabled frontend button','Trusting the tenant ID sent in the request body'],
    ['Every resource operation needs an authoritative ownership/access decision.','IDs can be guessed, copied, or observed.','Client controls can be bypassed.','Untrusted request fields cannot establish authorization.'],
    'Enforce authorization on reads, writes, exports, search results, and retrieval chunks. Test denied access explicitly, including background jobs.','Professional','https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html'),

  q('reliability',1,'Healthy jobs, stale data','All scheduled tasks are green, but the finance table is two days old. Which metric most directly detects the user impact?',
    ['Age of the latest complete business partition against the freshness objective','Number of green task icons','Number of lines of code','The scheduler’s logo color'],
    ['It measures whether the data consumers need is available on time.','Task success can coexist with empty or incorrect output.','Code size does not measure data freshness.','Visual appearance does not measure service health.'],
    'Measure outcomes, not only infrastructure activity. Pair freshness with completeness so a single new row cannot falsely mark an incomplete dataset healthy.','Starter'),
  q('reliability',2,'Turn a wish into an objective','Which statement is a measurable data service objective?',
    ['99% of daily sales partitions are complete by 07:00 local business time over a rolling 30 days','The pipeline should be fast','The team should try harder','Every query is perfect forever'],
    ['It names the event, threshold, time boundary, and measurement window.','Fast has no numerical threshold or measurement definition.','Effort is not a service outcome.','An absolute claim is neither a practical measurement nor a useful tradeoff.'],
    'Define “complete,” the business timezone, and the denominator. An objective is useful only when the team can measure and act on it.','Starter'),
  q('reliability',3,'An alert worth waking someone for','A job retries once and then finishes well before the deadline. Which alerting policy is usually more useful?',
    ['Page on actionable user-impact risk; record transient retries as lower-priority telemetry','Page every engineer for every retry','Never alert on any failure','Send an alert without the affected dataset or owner'],
    ['Severity should reflect impact, urgency, and a useful response.','Excessive pages train people to ignore noise.','Some failures threaten important commitments and need intervention.','An unactionable alert slows diagnosis.'],
    'Include symptom, scope, recent changes, a runbook, and ownership. Distinguish a recoverable event from sustained error-budget consumption.','Builder','https://sre.google/sre-book/practical-alerting/'),
  q('reliability',4,'Find the blast radius','A source column’s semantics changed. What does dataset and column lineage help determine?',
    ['Which downstream transformations and consumers may be affected','Whether the source values are automatically correct','How to avoid talking to any owner','The exact fix without inspecting logic'],
    ['Lineage maps dependencies that guide impact analysis.','Dependency metadata does not validate business truth.','Ownership and communication remain necessary.','The dependency map narrows investigation but does not infer every correction.'],
    'Capture job/run/dataset identity and relevant transformation metadata. Lineage is most useful when current, searchable, and tied to owners.','Builder','https://openlineage.io/docs/spec/object-model/'),
  q('reliability',5,'Restore proof, not backup hope','A backup job reports success every night. What establishes confidence in recovery?',
    ['Regular restore drills that verify usable data and measure recovery time and loss','The existence of a backup filename','A larger status badge','Assuming encryption guarantees restorability'],
    ['A restore test exercises the actual recovery path and its objectives.','A file may be incomplete, corrupt, inaccessible, or insufficient.','Presentation is not evidence of recovery.','Encryption can protect data but lost keys can also block a restore.'],
    'Define recovery time and recovery point objectives, verify dependencies and keys, and test the steps an on-call engineer would actually follow.','Professional','https://sre.google/sre-book/data-integrity/'),
  q('reliability',6,'A postmortem that changes the system','An engineer triggered a bad backfill using an ambiguous runbook. What is the strongest follow-up?',
    ['Explain contributing conditions and add clear safeguards, ownership, and verifiable actions','Write only the engineer’s name and blame them','Declare the event impossible to repeat without testing','Delete the logs to keep the record tidy'],
    ['System-focused analysis produces changes that reduce recurrence and impact.','Blame discourages learning and does not repair the failure path.','A claim without changed controls is unsupported.','Removing evidence impairs learning and auditability.'],
    'Include timeline, impact, detection, response, and causal contributors. Assign concrete actions with owners and a way to verify completion.','Professional','https://sre.google/sre-book/postmortem-culture/'),

  q('architecture',1,'Start from the user’s deadline','A retailer needs a complete stock report each morning, not second-by-second updates. What is a sensible starting architecture?',
    ['A reliable scheduled batch pipeline with measured completion and recovery','A complex streaming platform solely because it is newer','No tests because the report is daily','One giant synchronous request from the phone'],
    ['The design can meet the actual latency need with lower operational complexity.','Streaming may be justified later, but novelty is not a requirement.','Batch workloads still need correctness and recovery.','Long mobile requests are fragile and do not provide durable orchestration.'],
    'Choose from latency, volume, correctness, availability, skills, and cost requirements. Real time is a business constraint, not a universal badge of quality.','Starter'),
  q('architecture',2,'Estimate before choosing machines','A feed produces 2,000 events per second at 500 bytes each. Ignoring overhead and compression, what is its daily raw volume?',
    ['86.4 GB in decimal units','1 GB','86.4 MB','2 TB'],
    ['2,000 × 500 × 86,400 = 86,400,000,000 bytes.','1 MB/s reaches about 86.4 GB in one day.','That is off by a factor of 1,000.','The stated rate does not reach 2 TB per day.'],
    'This is a baseline, not provisioned capacity. Add replication, metadata, indexes, peak rates, retention, and growth before sizing the system.','Starter'),
  q('architecture',3,'Keep a replay path','A transformation bug is discovered after three weeks. Which design makes correction more practical?',
    ['Versioned transformation code plus retained source data and provenance within a defined retention policy','Only retaining the final aggregate with no source evidence','Mutating all raw records in place without history','Deleting failed records permanently'],
    ['Reproducible inputs and code enable controlled recomputation.','An aggregate may discard details needed to reconstruct the correct result.','In-place mutation destroys the original evidence.','Lost input cannot be recovered by changing transformation code.'],
    'Replay must also respect privacy retention, cost, and external side effects. Record source versions, job versions, and output lineage.','Builder'),
  q('architecture',4,'Protect the transactional database','Analysts repeatedly scan a large production orders table and slow checkout. What is a reasonable architecture response?',
    ['Separate analytical serving through an appropriate replica or ingestion path, with explicit freshness tradeoffs','Allow unlimited analytical scans on the checkout primary','Remove indexes required by checkout','Make customers wait for every dashboard refresh'],
    ['Isolation protects transactional latency while making data staleness visible.','Unbounded competing work threatens the business-critical path.','Removing needed indexes may worsen transactional performance.','Coupling checkout to analytics adds unnecessary failure and latency dependencies.'],
    'Operational and analytical workloads have different access patterns. Validate replication/CDC load and consistency needs rather than assuming separation has no cost.','Builder','https://www.postgresql.org/docs/current/hot-standby.html'),
  q('architecture',5,'Retrieval is not proof','A RAG tutor retrieves a paragraph about SQL from a trusted manual. What must still be checked?',
    ['That the passage actually supports the answer, matches the engine/version, and is cited correctly','Nothing; retrieval guarantees every generated sentence is true','Only whether the answer sounds confident','Whether the vector has many dimensions'],
    ['Relevant evidence and faithful generation are separate quality requirements.','A model can misread, overgeneralize, or introduce unsupported claims.','Confidence of tone is not correctness.','Embedding dimensions do not prove answer support.'],
    'Evaluate retrieval recall, citation support, answer correctness, and abstention separately. Query execution should grade SQL results; a tutor explains evidence.','Professional','https://arxiv.org/abs/2005.11401'),
  q('architecture',6,'Backlog and recovery capacity','A consumer handles 1,000 events/s while 800 events/s arrive. A one-hour outage creates 2.88 million queued events. At those rates, how long to catch up?',
    ['4 hours, because the net drain rate is 200 events/s','48 minutes, using the full 1,000 events/s as if arrivals stopped','1 hour exactly','It can never catch up'],
    ['2,880,000 / (1,000 − 800) = 14,400 seconds.','New arrivals consume most of the processing capacity.','Outage duration does not equal recovery duration.','Service exceeds arrivals, so a finite backlog can drain under stable conditions.'],
    'Recovery capacity needs headroom. Size for peaks and backlog drainage, not only steady-state average throughput.','Professional'),
  q('git',1,'A commit a reviewer can understand','A change fixes a currency conversion bug and also reformats the entire repository. What improves reviewability?',
    ['Separate the behavioral fix from unrelated formatting','Combine more unrelated changes into the same commit','Remove the tests from the diff','Use a commit message that only says update'],
    ['Focused changes make behavior, risk, and rollback easier to assess.','More unrelated work hides the important change.','Tests provide evidence for the intended behavior.','A vague message obscures the reason for the change.'],
    'A useful commit tells a coherent story. Reviewers should be able to identify the problem, the behavioral change, and the relevant validation.','Starter'),
  q('git',2,'Undo a published bad change','A faulty commit is already on a shared branch. You need a normal auditable reversal. Which command is usually appropriate?',
    ['git revert <commit>','git reset --hard followed by a force push without coordination','Delete the repository','Edit the commit message only'],
    ['Revert adds a new commit that reverses the selected change.','Rewriting shared history can disrupt other contributors and needs explicit coordination.','Deleting the repository destroys useful history and is unnecessary.','The message does not alter the faulty code.'],
    'A revert preserves the shared history. It may still require conflict resolution and testing, especially when later commits depend on the change.','Starter','https://git-scm.com/docs/git-revert'),
  q('git',3,'Resolve a merge conflict with intent','Two branches change the same revenue formula. What is the right resolution process?',
    ['Understand both intended behaviors, produce the correct combined result, and run focused tests','Always take whichever side is newer','Delete the conflict markers and keep both formulas executing','Assume Git can determine the business definition'],
    ['Conflict resolution is a semantic decision, not merely a text cleanup.','Recency does not establish correctness.','Keeping both may duplicate computation or conflict logically.','Version control cannot infer the intended metric definition.'],
    'Read surrounding code and the requirements. A syntactically clean merge can still be behaviorally wrong.','Builder'),
  q('git',4,'A secret entered history','A credential was committed and pushed, then deleted in a later commit. What is the urgent security action?',
    ['Revoke or rotate the credential, then coordinate history cleanup where needed','Assume the later deletion removes it from all history','Only rename the file','Make the repository description less obvious'],
    ['An exposed credential must be treated as compromised; cleanup alone cannot revoke copies.','Earlier commits and clones can retain the secret.','A filename change does not invalidate the credential.','Obscurity does not remove access.'],
    'Stop the exposure at its source by rotating the secret. Add secret scanning and a server-side secret workflow to reduce recurrence.','Professional','https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/removing-sensitive-data-from-a-repository'),
  q('linux',1,'The pipeline hid a failed command','In Bash, extract | compress returns success because compress succeeds even though extract failed. Which setting helps propagate an upstream failure?',
    ['set -o pipefail','chmod 777 on the output directory','Append an ampersand to every command','Redirect stderr to /dev/null'],
    ['pipefail changes pipeline status to reflect a failing component.','Permissions do not change pipeline exit-status semantics.','Background execution does not make failures visible automatically.','Discarding errors hides diagnostic evidence.'],
    'Also inspect exit status and clean incomplete outputs. Shell error handling has exceptions; test the failure paths instead of trusting a single setting.','Starter'),
  q('linux',2,'A path containing spaces','A Bash variable input_path contains /data/monthly sales.csv. How should it normally be passed as one path argument?',
    ['"$input_path"','$input_path without quotes','Split it into two filenames','Evaluate it as shell code'],
    ['Double quotes preserve the value as one argument while expanding the variable.','Unquoted expansion can split words and expand wildcard characters.','The file is one path, not two inputs.','Evaluation introduces injection risk and is unnecessary.'],
    'Quote path variables and use commands that handle arbitrary filenames. Data from users or files is not shell syntax.','Starter'),
  q('linux',3,'Disk full during an export','An export fails with no space left on device. What should you investigate before deleting files?',
    ['Filesystem usage, inode availability, and which known job-owned paths are consuming space','Recursively delete the root directory','Delete arbitrary database files','Run the export repeatedly without inspection'],
    ['Evidence identifies the actual constraint and a safe cleanup scope.','Deleting the filesystem is destructive and unrelated to a controlled recovery.','Database files require database-aware maintenance.','Repeated attempts can add more temporary output.'],
    'Use read-only inspection first. Distinguish byte capacity from inode exhaustion and follow retention policies for temporary and production data.','Builder','https://www.gnu.org/software/coreutils/manual/html_node/df-invocation.html'),
  q('linux',4,'Graceful process termination','A worker should finish or safely checkpoint in-flight work before stopping. Which shutdown design is appropriate?',
    ['Handle the normal termination signal, stop accepting work, and complete bounded cleanup before a deadline','Rely only on an uncatchable kill signal','Ignore every termination request forever','Mark every unfinished job successful'],
    ['A bounded graceful shutdown can preserve clear ownership and restart state.','An uncatchable kill gives the process no cleanup opportunity.','Ignoring shutdown can block deployment and recovery.','False success loses work or hides uncertainty.'],
    'Make the operation replay-safe even if graceful shutdown fails. Crash recovery must not depend on cleanup always running.','Professional','https://man7.org/linux/man-pages/man7/signal.7.html'),
  q('apis',1,'Retrying a payment request','A POST payment request times out after reaching the server. What does the timeout prove?',
    ['Only that the client did not receive a timely response; the payment may have happened','That the server definitely did nothing','That retrying with a new payment ID is always safe','That the payment definitely succeeded'],
    ['A network failure leaves the remote outcome uncertain.','The server may have completed before the response was lost.','A new ID can create a second payment.','No response does not establish success either.'],
    'Use the provider’s idempotency mechanism and query the operation status when supported. Preserve the same logical request key across retries.','Starter'),
  q('apis',2,'Stop at the real end of pagination','An API returns a next_cursor token. What should the client use to decide whether more pages exist?',
    ['The documented pagination contract, including the next cursor or terminal marker','Assume every page smaller than 100 rows is the last, regardless of the contract','Stop after the first successful HTTP response','Generate random cursor strings'],
    ['The server’s contract defines the correct continuation behavior.','Page size may vary for reasons other than exhaustion.','One page may contain only a fraction of the data.','Opaque cursors must be returned by the server, not invented.'],
    'Treat cursor tokens as opaque. Persist them only at a safe commit point and detect accidental cursor loops.','Starter'),
  q('apis',3,'A webhook arrives twice','A provider delivers the same webhook event twice. How should the receiver protect a non-repeatable business action?',
    ['Authenticate the message and deduplicate by a stable event ID before the effect','Trust every inbound payload and execute immediately','Deduplicate only by current arrival timestamp','Return an error forever for all duplicate events'],
    ['Authenticity and deduplication address separate risks.','Unauthenticated requests can forge events.','Each delivery has a different arrival time.','Perpetual failure can trigger endless redelivery; a processed duplicate can usually be acknowledged.'],
    'Store the deduplication record and business effect with appropriate atomicity. Verify signatures using the provider’s exact raw-body rules.','Builder'),
  q('apis',4,'A breaking API change','An API changes total from tax-inclusive to tax-exclusive while keeping the same JSON type. What should contract testing include?',
    ['Business semantics and representative examples, not only field presence and types','Only whether JSON parsing succeeds','Only HTTP status 200','Only response size'],
    ['Consumers depend on meaning as well as shape.','Valid JSON can carry semantically incompatible data.','A successful status does not validate metric meaning.','The payload can retain the same size while changing its meaning.'],
    'Version or coordinate semantic changes and test the downstream interpretation. Keep units, rounding, and inclusion rules explicit.','Professional'),
  q('formats',1,'A comma inside the address','A CSV field contains Manila, Philippines inside quotes. Which parsing approach handles it correctly?',
    ['A CSV parser configured for the producer’s delimiter, quote, and escape rules','Split every line on commas','Remove every quotation mark before splitting','Treat the row as JSON without conversion'],
    ['A format-aware parser respects quoted delimiters.','Naive splitting creates an extra field.','Removing quotes destroys information needed to identify field boundaries.','CSV and JSON have different grammars.'],
    'Agree on dialect, encoding, headers, and newline handling. Test embedded delimiters and multiline fields, not just simple samples.','Starter','https://docs.python.org/3/library/csv.html'),
  q('formats',2,'A large identifier in JavaScript','A JSON event contains an integer ID larger than JavaScript’s safe integer range. What representation can preserve its exact value across such clients?',
    ['A documented decimal string identifier','A JavaScript Number with no validation','Round it to the nearest thousand','Convert it to a Boolean'],
    ['A string preserves digits without numeric precision loss.','Number cannot exactly represent every sufficiently large integer.','Rounding changes identity and can create collisions.','A Boolean discards the identifier.'],
    'Identifiers need equality, not arithmetic. Make serialization contracts explicit, especially across languages with different numeric ranges.','Starter','https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number/MAX_SAFE_INTEGER'),
  q('formats',3,'A new field in an old Avro record','A new Avro reader expects a field absent from an older writer’s schema. What can allow schema resolution?',
    ['A compatible reader schema with an appropriate default for the missing field','Assuming the reader can invent any required value','Changing the filename extension','Ignoring the writer’s schema entirely'],
    ['Reader defaults can supply absent fields during schema resolution.','A meaningful default must be defined by the schema contract.','An extension does not alter encoded data or schema compatibility.','Avro resolution uses both writer and reader schemas.'],
    'Test compatibility in the intended direction. Reading old data with new code and reading new data with old code are different requirements.','Builder'),
  q('formats',4,'Compression and parallel reads','A huge text file is compressed as a single gzip stream. Why may this hinder distributed splitting?',
    ['Ordinary gzip streams do not generally provide arbitrary independent split points like splittable layouts','Compression always makes every file trivially splittable','Every worker can start decoding any byte without metadata','The file must be corrupted'],
    ['A sequential compression stream can limit independent partition reads.','Compression codecs and containers have different splitting properties.','Decoding may require preceding stream state.','A valid gzip file can still be unsuitable for parallel splitting.'],
    'Choose format, codec, and file sizing together. Columnar containers with independently readable groups can better match analytical parallelism.','Professional','https://hadoop.apache.org/docs/stable/hadoop-mapreduce-client/hadoop-mapreduce-client-core/MapReduceTutorial.html'),
  q('warehouse',1,'LIMIT is not a scan budget','In BigQuery, does SELECT * FROM a large table LIMIT 10 necessarily avoid scanning most table bytes?',
    ['No; LIMIT does not by itself guarantee reduced bytes read','Yes; it always reads exactly ten physical rows','Yes; all queries with LIMIT are free','Only if the table name is short'],
    ['A limit restricts returned rows, not necessarily scanned data.','Physical reading depends on the engine and query.','Billing depends on the pricing model and work performed.','Table-name length does not determine scan work.'],
    'Select needed columns, use eligible partition filters, and inspect estimated/actual bytes. Avoid transferring assumptions from a different database engine.','Starter'),
  q('warehouse',2,'Prune the dates you do not need','A BigQuery table is partitioned by event_date. Which query design supports pruning?',
    ['Use a supported filter that constrains the partitioning column to the needed dates','Read all dates and filter only in the phone','Sort results by customer name','Rename event_date to a prettier label in the UI'],
    ['An eligible partition predicate lets the engine skip unrelated partitions.','Client-side filtering occurs after unnecessary data work.','A result sort does not restrict the input partition range.','Presentation names do not change the physical predicate.'],
    'Check the engine’s partition-filter rules and the query plan. A filter that is logically similar may not always be recognized for pruning.','Starter'),
  q('warehouse',3,'Materialize a reused expensive result','Many dashboards repeatedly execute the same expensive aggregation. What tradeoff should guide materialization?',
    ['Saved query work versus refresh cost, storage, and acceptable staleness','Materialize every possible query forever','Never store any derived result','Assume cached data is always current'],
    ['Materialization moves work from reads to maintenance and introduces freshness considerations.','Unbounded materialization creates maintenance and storage costs.','Recomputation may be unnecessarily expensive for repeated workloads.','Cached or materialized data has a refresh policy.'],
    'Choose a grain that supports the actual consumers and verify refresh correctness. Measure total workload cost rather than one isolated query.','Builder'),
  q('warehouse',4,'Dialects are not interchangeable','A Snowflake example uses QUALIFY to filter a window function result. The lab executes SQLite. What should the learner do?',
    ['Use a subquery or CTE for SQLite and recognize QUALIFY as a dialect-specific feature','Assume any SQL keyword works in every engine','Rename QUALIFY to WHERE without changing query structure','Treat a syntax error as proof the business logic is wrong'],
    ['A CTE/subquery can expose the window result for an outer filter.','SQL engines differ in supported syntax and functions.','Window results generally cannot be filtered at the same query level by WHERE.','A dialect mismatch can cause a syntax error independently of the intended logic.'],
    'Separate relational reasoning from engine syntax. Run dialect-specific solutions on the actual engine before claiming compatibility.','Professional','https://docs.snowflake.com/en/sql-reference/constructs/qualify'),
  q('governance',1,'A dataset with no owner','A critical customer table has unclear definitions and no contact. Which catalog entry is most valuable?',
    ['Purpose, accountable owner, grain, field meanings, freshness, access policy, and lineage','Only the number of columns','Only a decorative description','Only the database password'],
    ['These details help consumers understand, trust, and responsibly use the data.','Column count does not explain semantics or accountability.','A vague description leaves operational questions unanswered.','Secrets must not be published in catalog metadata.'],
    'A catalog is useful when it supports decisions and incident response. Keep ownership and definitions current through a maintained workflow.','Starter'),
  q('governance',2,'Collect only what the job needs','A delivery-time analysis needs city and timestamps, but the source also offers full addresses and phone numbers. What is the preferable default?',
    ['Limit collection to fields required for the stated purpose','Collect all personal fields forever in case they become useful','Copy the fields into public test fixtures','Put phone numbers in metric labels'],
    ['Minimization reduces unnecessary exposure and governance burden.','Indefinite speculative collection creates avoidable risk.','Public fixtures can disclose personal information.','Telemetry can spread sensitive identifiers widely.'],
    'Document the purpose and retention policy. Use synthetic or appropriately de-identified test data rather than casually copying production personal records.','Starter'),
  q('governance',3,'Deletion across the data estate','An approved deletion workflow removes a person from the source but leaves warehouse exports and search indexes unchanged. What is missing?',
    ['A scoped propagation and verification process across derived copies and retention systems','A new source table name','A dashboard color change','A guarantee that deletion always means immediate removal from every backup regardless of policy'],
    ['Derived systems need explicit handling and evidence of completion under the applicable policy.','Renaming does not remove records.','Visual changes do not alter stored data.','Backup retention and legal obligations need a defined policy rather than an invented universal rule.'],
    'Map copies and owners, track workflow status, and verify the effective result. Privacy requirements depend on context; encode the organization’s reviewed policy.','Builder'),
  q('governance',4,'A reusable data product contract','Two teams disagree about what active_customer means. What should the producer publish?',
    ['An agreed business definition, calculation, time window, exclusions, owner, and change policy','A confident label with no definition','Only a SQL query with undocumented assumptions','Separate incompatible definitions under the same name without notice'],
    ['A shared contract makes the metric interpretable and changes reviewable.','A label alone cannot resolve the disagreement.','SQL is useful evidence but may hide business assumptions.','Silent semantic divergence breaks cross-team comparisons.'],
    'Make definitions executable where possible and pair them with examples and tests. Version semantic changes and notify affected consumers.','Professional'),
  q('observability',1,'Which signal answers how often?','You need the rate of parser failures over the last hour. Which signal is the natural primary tool?',
    ['A counter metric aggregated over time','A random screenshot','Only one example stack trace','The number of source-code files'],
    ['A counter supports rates and trend analysis over a time window.','A screenshot is not a reliable time series.','A trace or log explains an instance but not necessarily the overall rate.','Code-file count does not measure runtime failures.'],
    'Use metrics for aggregate behavior and logs/traces for context. Define the denominator to distinguish more traffic from a higher failure fraction.','Starter'),
  q('observability',2,'Follow one request through services','An ingestion request crosses an API, queue, and worker. What helps connect its telemetry?',
    ['Propagated trace/correlation context with stable run and request identifiers','A different random label in every component with no mapping','Logging only the current day','Removing all IDs from telemetry'],
    ['Shared context links related work across asynchronous boundaries.','Unrelated labels make causal reconstruction difficult.','A date is too coarse to isolate one request.','Redaction is important, but safe correlation identifiers remain valuable.'],
    'Carry context across queue messages deliberately. Avoid putting sensitive payloads into tracing baggage or unrestricted logs.','Starter','https://opentelemetry.io/docs/concepts/context-propagation/'),
  q('observability',3,'A metric label explosion','A metric uses event_id as a label, creating millions of unique time series. What is a better design?',
    ['Use bounded categorical labels for metrics and retain event-level IDs in controlled logs or traces','Add customer email as another label','Increase label variety indefinitely','Stop measuring all failures'],
    ['Bounded cardinality keeps aggregate telemetry manageable while preserving detailed investigation elsewhere.','Personal emails add both cardinality and privacy risk.','Unbounded series growth increases resource cost and query difficulty.','The solution is better signal design, not total blindness.'],
    'Choose dimensions that answer operational questions, such as service, error class, and environment. Measure the cost of telemetry itself.','Builder'),
  q('observability',4,'An average hides the tail','Most loads finish quickly, but a few miss the deadline badly. Which view helps reveal the problem?',
    ['Latency distribution and relevant percentiles, plus the count of deadline misses','Only mean latency','Only the fastest run','Only total successful runs'],
    ['Tail and deadline metrics expose the experience hidden by an average.','A low mean can coexist with severe slow outliers.','The fastest case says little about reliability.','Success counts omit how late successful work finished.'],
    'Choose metrics tied to consumer expectations. Percentiles need enough samples and a clear window; for daily jobs, individual run histories are also important.','Professional'),
  q('mlops',1,'A feature from the future','A fraud model’s training row uses a chargeback recorded two weeks after the payment it predicts. What is the problem?',
    ['Target leakage: the feature was not available at prediction time','A beneficial increase in historical accuracy with no downside','Only a formatting issue','A reason to remove the event timestamp'],
    ['Training must respect what the online decision could actually know.','Offline accuracy can become misleading when future information leaks in.','The problem is temporal availability, not formatting.','Removing timestamps makes leakage harder to prevent.'],
    'Use point-in-time-correct joins and distinguish event time from when a value became available. Validate with realistic temporal splits.','Starter'),
  q('mlops',2,'Reproduce a training dataset','A model is retrained after a source correction. What should identify the previous training data?',
    ['Versioned inputs/snapshots, transformation code, feature definitions, and split rules','Only the model’s friendly name','Only the laptop username','The current contents of a mutable table with no version'],
    ['These artifacts establish which data and logic produced the training set.','A name does not identify the input records.','A user identity does not capture the dataset.','Mutable current state cannot reliably reconstruct historical inputs.'],
    'Record lineage and dataset versions alongside model artifacts. Reproducibility requires data and environment details, not only a random seed.','Starter'),
  q('mlops',3,'Training and serving disagree','Training computes spend over 30 calendar days, but online serving uses the last 720 hours in another timezone. What should be aligned?',
    ['The feature’s exact time semantics and implementation across training and serving','Only the feature’s display label','Only the model file extension','Nothing; similar names guarantee equivalent values'],
    ['Different window definitions can produce systematic training-serving skew.','A shared label can hide different calculations.','Artifact extension does not control feature semantics.','Equivalent meaning requires a shared contract and validation.'],
    'Test feature parity on representative events, including daylight-saving and boundary cases. Monitor distributions and missingness after deployment.','Builder'),
  q('mlops',4,'A stale retrieval index','A policy document is deleted from the source, but a RAG system still retrieves its old chunks. What capability is missing?',
    ['Version-aware ingestion and deletion propagation for chunks, embeddings, and retrieval metadata','More confident answer wording','A larger embedding vector alone','A longer answer token limit'],
    ['The index must reflect lifecycle changes in its authoritative sources.','Confidence does not remove stale evidence.','Vector size does not establish source freshness.','Longer outputs can repeat the stale policy at greater length.'],
    'Track source identity, version, access controls, and index time. Evaluate retrieval freshness and permission filtering as part of data quality.','Professional','https://arxiv.org/abs/2005.11401'),
];

function g(track:TrackId,n:number,title:string,body:string,example:string,tags:string[],source=sources[track]):Guide {
  return {id:`guide-${track}-${n}`,track,title,body,example,tags,source};
}
export const guides:Guide[] = [
  g('sql',1,'Think in rows before writing joins','Start by stating the grain of each input and the desired output. A join can multiply rows when either side has multiple matches. Count rows and distinct business keys before and after the join. If two child tables both contain many rows per parent, aggregate each to the desired grain first. DISTINCT may hide a symptom while leaving the metric wrong.','Order 42: 2 items × 3 payment attempts = 6 joined rows.\nAggregate payments to one row per order before joining to order totals.',['joins','grain','fanout','duplicates'],'https://www.postgresql.org/docs/current/queries-table-expressions.html'),
  g('sql',2,'Window functions retain the row','GROUP BY collapses rows into groups. A window function computes across related rows while retaining row identity. PARTITION BY defines the group, ORDER BY defines sequence, and the frame defines which rows participate in frame-sensitive calculations. Explicit frames and unique tie-breakers make intent clearer. Check NULL ordering and frame behavior in the engine you actually use.','SELECT event_id, device_id,\n  ROW_NUMBER() OVER (PARTITION BY device_id\n    ORDER BY event_time DESC, event_id DESC) AS rn\nFROM events;',['window','row_number','ranking','frame'],'https://www.postgresql.org/docs/current/tutorial-window.html'),
  g('python',1,'Streaming is an end-to-end property','Reading with an iterator avoids loading the whole input, but appending every result to a list loses that benefit. Use bounded batches, explicit encodings, context managers, and clear malformed-record handling. Choose batch limits from memory measurements. An input record can itself be unusually large, so a robust design also bounds record size.','with open(path, encoding="utf-8") as source:\n    for line in source:\n        record = parse(line)\n        write_record(record)',['memory','iterator','files','batch'],'https://docs.python.org/3/tutorial/inputoutput.html'),
  g('python',2,'Separate retryable errors from bad data','Network timeouts and throttling may be transient. An invalid schema or missing required field usually needs a different response. Set request timeouts, bounded retries, and backoff; preserve enough redacted context to diagnose failure. Quarantine is a policy, not a universal answer: some datasets must fail the entire partition if any record is invalid.','Transport timeout → bounded retry.\nInvalid currency code → reject or quarantine by contract.\nExpired credentials → alert and repair authentication.',['errors','retry','quarantine','validation'],'https://docs.python.org/3/tutorial/errors.html'),
  g('modeling',1,'Write the grain as a sentence','A fact table needs one unambiguous answer to “what does a row represent?” Choose the business process and grain before measures. An order-line fact can contain quantity and line amount; repeating order-level shipping cost on every line requires an allocation rule. Dimensional context should describe the event at the intended time.','Grain: one row per order_id + line_number.\nMeasures: quantity, unit_price, line_discount, net_line_amount.',['grain','facts','dimensions','star schema']),
  g('modeling',2,'Preserve history with effective intervals','Type 2 dimensions keep a separate version when tracked attributes change. A fact must resolve to the version effective at the event time, or store the resolved surrogate key. Use nonoverlapping intervals and a consistent boundary convention. Late corrections require a deliberate repair process; history tracking does not make source data infallible.','customer_key | customer_id | city   | valid_from | valid_to\n101          | C7          | Manila | 2026-01-01 | 2026-06-01\n153          | C7          | Cebu   | 2026-06-01 | NULL',['scd','history','effective date','surrogate key']),
  g('ingestion',1,'A checkpoint is a promise','A durable checkpoint claims that input before a position has been handled according to the pipeline contract. Advance it only when output is durable or coordinated by a transaction. If a crash can occur between output and checkpoint, design for replay and deduplication. Keep source position separate from the time your worker happened to run.','Read page → validate → commit output → persist next cursor.\nCrash before cursor commit → replay the page safely.',['checkpoint','cursor','replay','idempotence']),
  g('ingestion',2,'CDC carries operations, not just rows','Change data capture describes inserts, updates, and deletes from a source log. A bootstrap snapshot must connect safely to ongoing changes. A sink needs keys, source ordering, and a policy for repeated deliveries. Preserve source metadata needed to debug gaps or stale updates. Hard deletes need explicit handling; a timestamp query over existing rows cannot discover vanished records.','Source event: key=order_83, op=delete, position=...\nHistory sink: retain the event.\nCurrent-state sink: remove or mark the entity according to policy.',['cdc','delete','snapshot','change log']),
  g('orchestration',1,'Treat a logical run as repeatable','A run should target a stable input interval and converge on a defined output. Select the intended partition, avoid using the current clock as business input, and write through a replace/merge or commit pattern. A scheduler retry does not roll back an external API call. Separate irreversible side effects and give them idempotency keys or coordinated delivery.','Logical interval: [2026-11-01, 2026-11-02).\nRetry on November 5 still processes November 1.',['airflow','idempotence','data interval','retry']),
  g('orchestration',2,'Backfill as a controlled production workload','A backfill competes with current work for database connections, compute, storage requests, and operator attention. Estimate its size, bound concurrency, test a small interval, and record the code version. Verify the result before advancing the backfill. Avoid silently recomputing history with changed business logic unless that is the intended migration.','Plan: one day → validate totals → one week → bounded full range.\nGuardrail: pause if the live dataset approaches its freshness deadline.',['backfill','pools','concurrency','recovery']),
  g('quality',1,'Use different tests for different questions','Unit tests exercise transformation logic on controlled inputs and expected outputs. Data tests assert properties of materialized data. Freshness checks measure recency. Reconciliation checks compare independent totals or coverage. None proves all the others. Pick tests from plausible failure modes, including missing rows, duplicates, boundary dates, and semantic changes.','Unit: a shipment at the deadline is on time.\nData: shipment_id is unique and not null.\nReconcile: loaded source partitions match the manifest.',['dbt','unit tests','data tests','freshness'],'https://docs.getdbt.com/docs/build/unit-tests'),
  g('quality',2,'Incremental logic needs a mutation contract','A high-water mark is correct only under assumptions about source ordering, updates, and deletes. A lookback can recover bounded late arrivals; it cannot cover arbitrarily old corrections. A merge needs a stable key and a deterministic winner. Keep a full-refresh or targeted-repair path and compare incremental output against a trusted recomputation on representative fixtures.','Input contract: updates may arrive up to 72 hours late.\nModel: revisit that window and merge by order_id.\nOut-of-contract correction: targeted historical repair.',['incremental','merge','late data','lookback'],'https://docs.getdbt.com/docs/build/incremental-models'),
  g('spark',1,'Read the plan before adding workers','A slow distributed job can be limited by input I/O, shuffle, skew, CPU, spill, or a slow sink. Inspect physical operators and task distributions. A single huge partition will not automatically become balanced when more executors are added. Reduce unnecessary columns and rows, choose joins from actual sizes, and compare before/after metrics.','Evidence: 199 tasks finish in 15 s; one takes 900 s.\nHypothesis: skew or an unusually large partition.\nCheck task input/shuffle sizes before changing cluster size.',['spark','plan','shuffle','skew']),
  g('spark',2,'Broadcast, shuffle, and memory','A broadcast join copies a sufficiently small side to workers so the large side can avoid some redistribution. It is useful only when the join supports it and the copy fits safely. A shuffle redistributes by keys and can spill to disk. Adaptive execution can improve plans from runtime statistics, but it does not replace good data layout and validation.','Large fact + small country dimension → consider broadcast.\nTwo large facts → inspect shuffle strategy and key distribution.',['broadcast','join','aqe','memory']),
  g('streaming',1,'Make event-time promises explicit','Event time describes when the business event occurred. Processing time describes when a system handles it. Watermarks express progress assumptions so event-time operations can decide when to emit results. Late events remain possible. Decide whether they update results, go to a side output, or are dropped with measurement. The policy affects both correctness and latency.','Event occurred 09:00; arrived 09:07.\nA 09:00 window needs a documented late-arrival policy.',['event time','watermark','lateness','windows']),
  g('streaming',2,'Name the boundary of exactly-once','Exactly-once is meaningful only for a specified operation and boundary. A processor may restore state consistently while an external HTTP call still happens twice. Transactions, checkpoint coordination, idempotency keys, and deduplication each solve different parts. Describe what is replayed, what is committed, and what consumers can observe after failure.','Kafka input → transaction → Kafka output: coordinated boundary.\nKafka input → external payment API: payment API cooperation still required.',['exactly once','transactions','kafka','side effects'],'https://kafka.apache.org/41/design/design/'),
  g('lakehouse',1,'File format and table format are different layers','Parquet stores typed columnar data inside files. Iceberg manages a table’s files and metadata, including snapshots and evolution. An engine executes queries using these layers. A catalog locates and coordinates table metadata. Distinguish these roles when choosing components; a storage bucket alone is not a complete transactional table system.','Object storage → Parquet files → Iceberg metadata → catalog → query engine.',['parquet','iceberg','catalog','storage'],'https://iceberg.apache.org/docs/latest/reliability/'),
  g('lakehouse',2,'Maintenance has a correctness boundary','Compaction can reduce small-file overhead. Snapshot expiration and orphan-file cleanup reclaim storage under specific rules. These are separate operations and must respect retained snapshots, reader duration, rollback needs, and concurrent writers. Use table-aware tooling and verify retention settings before deleting physical files. A cheap cleanup that breaks recovery is not an optimization.','Maintain: compact small files.\nRetain: snapshots needed by recovery policy.\nDelete: only files proven safe by the table-aware procedure.',['compaction','retention','snapshots','maintenance'],'https://iceberg.apache.org/docs/latest/maintenance/'),
  g('cloud',1,'Protect secrets at the trust boundary','Anything sent to a browser can be inspected by its user. Keep shared service credentials in a server-side secret system. Authenticate the caller, authorize the requested resource, and limit costly operations. Use short-lived credentials where supported. Redact secrets in logs and rotate exposed credentials; deleting them from the current file does not revoke copies.','Phone → authenticated backend → provider API.\nThe provider key stays on the backend.',['secrets','api keys','authorization','mobile'],'https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html'),
  g('cloud',2,'Optimize cost per useful outcome','A lower monthly bill can hide lower data quality or missed deadlines. Attribute cost to jobs, environments, and teams, then compare it to useful output: partitions refreshed, queries served, or events processed within the objective. Inspect scan volume, redundant work, idle resources, and storage retention. Validate correctness and latency after every optimization.','Measure: cost per million validated events.\nGuardrails: freshness, completeness, error rate, and recovery headroom.',['cost','finops','budgets','efficiency'],'https://docs.aws.amazon.com/wellarchitected/latest/cost-optimization-pillar/welcome.html'),
  g('reliability',1,'Measure the data consumer’s experience','A healthy scheduler does not guarantee useful data. Define indicators for freshness, completeness, correctness, and availability where each matters. An objective needs a threshold, denominator, time window, and owner. For a daily report, the age of the latest complete partition can be more meaningful than the number of successful tasks.','Objective: 99% of daily sales partitions complete by 07:00\nover a rolling 30-day window, using the business timezone.',['slo','sli','freshness','completeness']),
  g('reliability',2,'Recover with a runbook and proof','An incident response should establish impact, contain harm, gather evidence, and restore a known-good state. Record what was replayed or repaired and reconcile the output before declaring recovery. A runbook needs commands or procedures, owners, rollback criteria, and verification. Practice restores before an outage exposes missing permissions or unavailable keys.','Detect → scope → contain → repair/replay → reconcile → communicate → learn.',['incident','runbook','restore','postmortem'],'https://sre.google/sre-book/managing-incidents/'),
  g('architecture',1,'Choose a design from constraints','Start with consumers and decisions: required latency, data volume, mutation behavior, correctness, availability, access, retention, team skills, and budget. State assumptions and calculate a baseline. Draw data flow and failure boundaries before choosing products. A simpler batch design can be the professional choice when it meets the requirement.','2,000 events/s × 500 bytes × 86,400 s = 86.4 GB/day raw.\nThen account for peaks, replicas, indexes, retention, and replay.',['system design','capacity','tradeoffs','batch']),
  g('architecture',2,'A tutor should explain evidence','Separate deterministic checks from generated explanations. A SQL engine can execute a candidate against fixtures and produce result differences. Retrieval can bring relevant, versioned documentation. A tutor should cite supporting passages, distinguish inference, and admit when evidence is insufficient. Evaluate correctness and citation support independently; a fluent response is not a test result.','SQL result mismatch → row/column evidence → relevant manual passage\n→ explanation and a targeted next exercise.',['rag','grading','citations','evaluation'],'https://arxiv.org/abs/2005.11401'),
  g('git',1,'Make engineering work reviewable','Keep a change focused on one coherent behavior. Include a concise reason, a concrete before/after, and validation relevant to the risk. Commit generated artifacts only when the project needs them. Lock dependencies for reproducibility and keep secrets out of source. A review is easier when unrelated formatting and feature work are separated.','Change: prevent duplicate order loads on retry.\nEvidence: retry fixture produces one row per order_id.',['git','review','commits','ci']),
  g('git',2,'Reverse shared changes without hiding history','A revert records a new change that undoes an earlier commit. A reset or rebase rewrites history and can disrupt shared work. Choose based on whether the history is private or published and coordinate any rewrite. Test the resulting behavior: later changes may depend on the reverted code, and a clean textual revert is not proof of a healthy system.','git revert <bad-commit>\n# Resolve any conflicts, inspect the diff, then run relevant checks.',['revert','rollback','history','branches'],'https://git-scm.com/docs/git-revert'),
  g('linux',1,'Make shell failures visible','A shell pipeline has multiple exit statuses. In Bash, pipefail helps expose an upstream failure that would otherwise be masked by a successful last command. Quote variables used as arguments, avoid evaluating untrusted data as code, and inspect failure paths. Use temporary output plus a safe publish step so a failed command does not leave a plausible-looking final artifact.','set -o pipefail\nextract_data | compress_data > temporary_output\n# Publish only after checking successful completion.',['bash','exit status','pipefail','quoting']),
  g('linux',2,'Inspect before changing the machine','When a job fails, gather bounded evidence: exit code, stderr, process state, memory pressure, disk bytes/inodes, and permissions on the intended paths. Do not use broad deletion or world-writable permissions as a universal fix. Distinguish a data error from a resource or access error. Record the narrow remediation and verify the original workload afterward.','Disk issue: identify the filesystem and job-owned temporary files.\nPermission issue: inspect the required user, group, and path access.',['linux','disk','permissions','processes'],'https://www.gnu.org/software/coreutils/manual/coreutils.html'),
  g('apis',1,'Timeout means uncertainty','A timeout means the client did not receive a response in time. It does not prove the server did nothing. Retrying a write can duplicate a business action unless the service offers suitable idempotency or status lookup. Use bounded retries, explicit connect/read timeouts, and a stable logical operation identifier. Treat authentication and validation failures differently from transient overload.','request_id=payment_2026_483\nRetry the same logical operation with the same supported idempotency key.',['http','timeout','idempotency','retry']),
  g('apis',2,'Pagination is a state machine','Follow the API’s documented continuation token or page contract. Tokens may be opaque and may expire. Detect repeated tokens, honor rate limits, and advance durable state only after committing the page. Mutable datasets can shift during offset pagination; use a source-supported cursor or snapshot when consistency matters. Test empty pages, final pages, and restart behavior.','State: cursor → fetch → validate → durable write → next cursor.\nTerminal state comes from the API contract, not a guessed token.',['pagination','cursor','rate limits','restart']),
  g('formats',1,'Preserve meaning across serialization','A field’s type, unit, timezone, precision, nullability, and encoding all matter. An integer amount might mean cents or dollars. A timestamp string may omit its offset. A large numeric identifier may lose precision in a JavaScript client. Define the contract and test round trips through every relevant producer and consumer language.','amount_minor: 1999\ncurrency: PHP\nobserved_at: 2026-11-05T08:30:00+08:00\ncustomer_id: "9007199254740993"',['schema','precision','units','serialization']),
  g('formats',2,'Test schema evolution in both directions','Compatibility depends on which writer and reader versions meet. A new reader may need defaults for fields absent in old data; an old reader may ignore new fields or reject incompatible types depending on the format. Run compatibility checks against retained data and deployed consumers. A schema registry can enforce rules, but semantic unit changes still need review.','Case A: new reader + old writer.\nCase B: old reader + new writer.\nBoth cases need explicit expectations.',['avro','evolution','compatibility','defaults']),
  g('warehouse',1,'Reduce work at the storage boundary','Select only needed columns and use predicates that the engine can apply to partitions or storage blocks. Inspect plans and scan estimates. LIMIT may reduce returned rows without reducing bytes scanned, especially in columnar cloud warehouses. Clustering and partitioning should reflect common filters and data distribution, not a generic rule copied from another system.',"SELECT customer_id, amount\nFROM orders\nWHERE event_date >= DATE '2026-11-01';",['partition','pruning','bigquery','scan cost']),
  g('warehouse',2,'Learn the idea and the dialect','The same analytical task can use different syntax across SQLite, PostgreSQL, MySQL, BigQuery, and Snowflake. Date arithmetic, JSON operations, casting, NULL ordering, and window filtering differ. Label examples with their engine and version. A reference tab is not an execution engine. Validate runnable solutions on the actual backend and test edge cases.','Snowflake/BigQuery: QUALIFY can filter a window result.\nSQLite/PostgreSQL: use an outer SELECT over a CTE/subquery.',['dialect','qualify','sql','portability'],'https://docs.snowflake.com/en/sql-reference/constructs/qualify'),
  g('governance',1,'Ownership makes a dataset usable','A useful data product states its purpose, grain, semantics, owner, service expectations, access rules, and change policy. A catalog helps consumers discover it, but documentation without maintenance decays. Connect ownership to incident response and review. Include examples that clarify ambiguous definitions such as active, complete, refunded, and on time.','Dataset contract: daily completed deliveries.\nOwner: logistics analytics.\nGrain: one completed delivery.\nDeadline: defined by the published data objective.',['catalog','ownership','data contract','semantics']),
  g('governance',2,'Retention is part of the data lifecycle','Every copy has a purpose, access policy, and lifetime: raw storage, transformed tables, exports, logs, backups, and retrieval indexes. Deletion and correction workflows need to account for derived copies. Use the organization’s reviewed requirements rather than assuming one universal retention period. Record decisions, propagate changes, and verify completion at the relevant systems.','Source correction → warehouse repair → export refresh → search/index update.\nTrack each step with an owner and evidence.',['retention','privacy','deletion','lifecycle']),
  g('observability',1,'Give each telemetry signal a job','Metrics summarize behavior over time. Logs describe discrete events. Traces connect work across components. Use them together with safe correlation identifiers. A metric can reveal an error-rate increase; a trace can locate a slow dependency; a log can explain the specific failure. Data-specific signals such as missing partitions complement infrastructure telemetry.','Metric: rejected_records_total{error_class="schema"}\nTrace: API → queue → ingestion worker.\nLog: redacted record reference and validation rule.',['metrics','logs','traces','opentelemetry']),
  g('observability',2,'Keep cardinality and privacy under control','A unique event ID or email as a metric label can create enormous numbers of time series and expose sensitive data. Prefer bounded categories for metrics. Keep detailed identifiers in access-controlled logs or traces with a retention policy. Sampling reduces volume but can hide rare failures, so design error retention and aggregate metrics deliberately.','Good metric labels: service, environment, error_class.\nAvoid unbounded labels: event_id, raw URL query, customer_email.',['cardinality','sampling','privacy','telemetry']),
  g('mlops',1,'Build features as of the decision time','A training feature must reflect information available when the prediction would have been made. Event time alone is not always enough: a correction can describe an old event but arrive later. Use point-in-time joins with availability semantics, realistic temporal splits, and versioned inputs. Future labels or outcomes must not leak into predictors.','Payment at 10:00.\nChargeback learned two weeks later.\nThe chargeback cannot be a feature for the 10:00 decision.',['leakage','features','point in time','training']),
  g('mlops',2,'Treat a vector index as a derived dataset','Retrieval chunks and embeddings come from source documents with identities, versions, access policies, and deletion rules. Preserve provenance, update changed documents, remove stale chunks, and filter permissions before returning evidence. Evaluate retrieval recall and freshness separately from generated answer quality. Re-embedding can require an index migration when the embedding model changes.','Document v3 → chunk IDs + source version + access metadata → embeddings.\nDelete document → remove its retrievable chunks and verify absence.',['rag','vectors','embeddings','provenance'],'https://arxiv.org/abs/2005.11401'),
];

function decision(n:number,prompt:string,options:string[],why:string[],explanation:string):Decision {
  const offset=n%options.length;
  return {prompt,options:[...options.slice(offset),...options.slice(0,offset)],answer:(options.length-offset)%options.length,why:[...why.slice(offset),...why.slice(0,offset)],explanation};
}
export const incidents:Incident[] = [
  {id:'incident-retry',title:'The revenue that arrived twice',track:'orchestration',difficulty:'Builder',summary:'A daily retail load retried after a worker crash. Finance sees twice the expected revenue. Diagnose the failure and choose a safe recovery.',logs:['06:01 load_sales interval=2026-11-04 attempt=1','06:04 target insert committed rows=12480','06:04 worker connection lost before task acknowledgement','06:06 load_sales interval=2026-11-04 attempt=2','06:09 target insert committed rows=12480','06:15 reconciliation: target orders=24960, source orders=12480'],source:sources.orchestration,steps:[
    decision(1,'The first insert committed before the worker crashed. Which explanation best fits the doubled total?',['The retry appended the same logical rows again','The source necessarily created 12,480 new real orders in two minutes','A successful SQL commit automatically marks the scheduler task complete'],['The log shows two committed inserts for the same interval.','The source reconciliation contradicts this hypothesis.','The database and scheduler acknowledgement are separate boundaries.'],'A crash between an output commit and task acknowledgement creates an uncertain outcome. Repeating an append can duplicate the business effect.'),
    decision(2,'You have verified stable order IDs and a complete source partition. What is a controlled recovery?',['Pause downstream publication, rebuild the affected partition from verified input, and reconcile before republishing','Delete every sales partition in the warehouse','Keep one arbitrary half of the rows without checking keys'],['A scoped rebuild restores the intended logical result and validates it.','The incident is limited to one interval; broad deletion increases harm.','Arbitrary row removal may discard legitimate records and keep duplicates.'],'Preserve evidence and limit the repair to the known scope. Verify row counts, unique keys, and revenue totals before declaring the dataset recovered.'),
    decision(0,'Which prevention directly addresses the failure mode?',['Use a stable interval with an idempotent merge or partition-replacement commit, tested under a crash/retry fixture','Set the retry count to 20','Rename the task to safe_load'],['The write converges on one intended result across repeated attempts.','More retries can create more duplicates if writes remain append-only.','A name does not change failure semantics.'],'Test the exact interruption boundary: output committed, acknowledgement absent. The next attempt should produce the same final dataset, not another copy.'),
  ]},
  {id:'incident-join',title:'A dashboard with impossible margins',track:'sql',difficulty:'Builder',summary:'A new report joins order lines and payment attempts. Revenue jumps, but the source system is unchanged. Trace the grain mismatch.',logs:['Model changed: orders JOIN order_lines JOIN payment_attempts','Order O-81: 3 lines, line revenue total=900','Order O-81: 2 payment attempts, one successful','Joined result: 6 rows for O-81','Dashboard reported revenue for O-81=1800'],source:'https://www.postgresql.org/docs/current/queries-table-expressions.html',steps:[
    decision(2,'What is the strongest initial diagnosis?',['Each order line was repeated for each matching payment attempt','The customer paid exactly twice because there are two attempts','GROUP BY always doubles monetary values'],['Three lines times two attempts yields six rows and duplicates line revenue.','An attempt is not necessarily a successful payment.','Grouping aggregates the input rows; the multiplication happened in the join.'],'Identify the grain of each child relation. The report accidentally combines two one-to-many relationships before aggregation.'),
    decision(0,'The report needs revenue from paid orders, at order grain. Which design is clearest?',['Aggregate lines to order totals and join to one qualifying payment record or an existence test','Use SUM(DISTINCT line_amount) as a universal fix','Remove order_id from the GROUP BY'],['The design expresses the desired grain and eligibility separately.','Equal amounts on different legitimate lines would be incorrectly collapsed.','Removing the key does not undo duplicated amounts.'],'A correct query follows the business definition: one total per order and a clear rule for what counts as paid.'),
    decision(1,'Which regression fixture is most valuable?',['An order with multiple equal-priced lines, failed and successful payment attempts, plus an unpaid order','Only an order with one line and one payment','A table with no rows and no expected result'],['It tests fanout, the DISTINCT trap, and payment eligibility.','A one-to-one sample hides the bug.','An empty sample alone cannot establish the intended calculation.'],'Tests should distinguish a genuinely correct solution from plausible shortcuts. Expected totals must be independently specified.'),
  ]},
  {id:'incident-watermark',title:'The window that would not close',track:'streaming',difficulty:'Professional',summary:'A transit feed is still processing events, but hourly passenger totals stop finalizing. Inspect event-time progress and late-data policy.',logs:['Input partition 0: latest event_time=10:12, watermark=10:10','Input partition 1: latest event_time=10:11, watermark=10:09','Input partition 2: no events since 08:42, watermark=08:40','Window [09:00,10:00): still open','CPU=35%; sink latency normal'],source:sources.streaming,steps:[
    decision(0,'Which evidence best explains the stalled event-time window?',['The idle partition is holding back combined watermark progress','CPU is definitely too low to calculate a sum','The sink must be down despite normal sink latency'],['The slowest active input can constrain event-time progress.','Low CPU can be consistent with waiting for progress rather than computation.','The supplied evidence does not point to the sink.'],'The job can process records while event-time completion is stalled. Inspect input activity and watermarks separately from throughput.'),
    decision(1,'The source contract permits partitions to go quiet. What is a suitable change?',['Configure and test appropriate input-idleness handling, with a policy for late events when the partition resumes','Set the watermark to year 2099','Discard every event from partition 2 forever'],['Idleness handling can let active inputs progress while resumed data follows a defined lateness policy.','An arbitrary future watermark can prematurely close windows and lose correct handling.','Permanent deletion of one source partition is not justified.'],'Idleness is a semantic decision. Choose a timeout from source behavior and test quiet, resumed, and genuinely delayed partitions.'),
    decision(2,'Partition 2 resumes with events from 09:15 after the window was emitted. What should happen?',['Apply the documented correction/late-output/drop policy and measure the late events','Assume the events never existed','Silently add them to the current hour'],['The response must match the product’s correctness and latency contract.','Ignoring evidence hides loss.','Reassigning event time changes the business meaning.'],'A finalized result needs a correction policy if later evidence can arrive. Make revisions or dropped-late counts visible to consumers.'),
  ]},
  {id:'incident-skew',title:'One task, forty minutes',track:'spark',difficulty:'Professional',summary:'A delivery analytics join misses its deadline. Most tasks finish quickly, while one partition spills heavily. Choose an evidence-led optimization.',logs:['Join key: courier_id','Tasks 1–199: median duration=18 seconds','Task 200: duration=2400 seconds; spill=96 GB','Key UNKNOWN represents 46% of incoming rows','Executor CPU is uneven; most executors are idle near job end'],source:sources.spark,steps:[
    decision(1,'What hypothesis is best supported?',['A hot UNKNOWN key concentrates join work into a straggler partition','Every task is equally slow because the cluster is too small','The output file extension causes the join to wait'],['The key distribution and one large spilling task indicate skew.','The task durations and idle executors show an imbalance.','The evidence concerns keyed join work, not filename handling.'],'Use task-level distributions, not only job duration. Additional workers may sit idle if one key still owns most of the work.'),
    decision(2,'What should you decide before salting or filtering the UNKNOWN key?',['Its business meaning and required join behavior, then evaluate a correct skew strategy','Delete all UNKNOWN rows without consulting the contract','Randomize the join keys independently on both sides'],['A performance fix must preserve required rows and matches.','Unknown data may still represent legitimate activity.','Independent randomization breaks matching relationships.'],'Possible strategies include separately processing a special key, pre-aggregation, or adaptive skew handling. Validate semantics before optimizing mechanics.'),
    decision(0,'How do you establish that the chosen change helped?',['Compare full output/reconciliations and task distributions, runtime, spill, and cost on representative data','Report only that the code is shorter','Check only the fastest task','Skip validation because the job completed'],['Correctness and resource evidence together establish a useful improvement.','Code length is not a performance or correctness metric.','The tail task caused the incident.','Completion can still produce missing or duplicated rows.'],'Retain a regression fixture with the skewed key. Record the workload size and configuration so the comparison is meaningful.'),
  ]},
  {id:'incident-cdc',title:'The deleted customer still appears',track:'ingestion',difficulty:'Professional',summary:'The source removed an account, but its warehouse profile and retrieval index remain active. Follow the deletion event through the pipeline.',logs:['Source log: customer_id=C-904 op=delete position=78104','CDC transport: event acknowledged','Warehouse consumer: ignored op=delete (unsupported branch)','Search index: last update version=78101','User-facing lookup still returns C-904'],source:sources.ingestion,steps:[
    decision(2,'Where is the first confirmed break in the deletion path?',['The warehouse consumer ignores the delivered delete operation','The source failed to emit a delete','The transport definitely lost every event'],['The logs explicitly show the consumer’s unsupported branch.','A source delete is present in the evidence.','The event was acknowledged and reached the consumer.'],'Trace the operation through each boundary. Do not rebuild the source connector when evidence already identifies a downstream semantic gap.'),
    decision(0,'What is the appropriate repair scope?',['Apply the approved deletion policy to affected warehouse and index records, replay safely, and verify absence where required','Delete all customers from every system','Only hide the row in the frontend while retaining unrestricted search access'],['The repair covers derived copies and includes verification.','The incident does not justify deleting unrelated data.','A visual filter leaves other access paths and derived records unchanged.'],'Coordinate the lifecycle across derived datasets. Follow the reviewed retention and deletion policy, including any legitimate exceptions.'),
    decision(1,'Which regression test best prevents recurrence?',['Insert → update → delete → replay-delete, checked in both the current-state sink and derived index','An insert-only happy path','Only a test that the connector process starts'],['It exercises lifecycle operations and repeated delivery across affected systems.','Insert-only tests miss delete semantics.','Process startup does not verify data behavior.'],'Monitor unsupported operation counts and propagation lag. An acknowledged transport event is not proof that every derived system applied it correctly.'),
  ]},
  {id:'incident-rag',title:'The tutor cites an obsolete manual',track:'mlops',difficulty:'Professional',summary:'A SQL tutor confidently recommends a feature unavailable in the learner’s engine. Its citation points to an old indexed document. Repair the evidence path.',logs:['Learner engine=SQLite; tutor answer uses QUALIFY','Retrieved chunk: engine=Snowflake, source_version=2023-09','Current source metadata: version=2026-10','Answer marked confident; no engine constraint applied','SQL runner result: syntax error near QUALIFY'],source:'https://docs.snowflake.com/en/sql-reference/constructs/qualify',steps:[
    decision(0,'What does the evidence establish?',['The explanation ignored engine context and retrieved mismatched/stale evidence','The SQL runner should accept every dialect','The learner’s question is necessarily invalid'],['The retrieval metadata and runtime error show a dialect mismatch and stale version.','Each engine implements its own supported syntax.','A valid business question can have a dialect-specific solution.'],'Preserve the deterministic runner as the authority for execution. A tutor must adapt its explanation to the actual engine and available evidence.'),
    decision(1,'What is the strongest immediate tutor behavior?',['Explain the dialect mismatch, cite the relevant source, and offer a SQLite CTE/subquery equivalent that is actually tested','Claim the query passed despite the engine error','Remove citations and keep the same answer'],['It corrects the unsupported claim and grounds the suggested repair.','False success undermines learning and trust.','Removing provenance hides rather than fixes the evidence problem.'],'A transparent correction can teach SQL portability. Distinguish a source-backed syntax fact from an inferred debugging suggestion.'),
    decision(2,'What should the retrieval pipeline add?',['Engine/version-aware metadata filters, source update/deletion handling, and eval cases for mismatched evidence','Only a larger answer token budget','A rule that every answer must sound certain'],['These changes address selection, freshness, and measured failure behavior.','Longer output does not improve evidence compatibility.','Forced confidence makes unsupported answers harder to recognize.'],'Evaluate retrieval relevance, citation support, executable correctness, and abstention separately. Keep old source versions only with explicit historical context.'),
  ]},
];

export const projects:Project[] = [
  {id:'project-retail',title:'A trustworthy retail warehouse',summary:'Turn orders, line items, payments, and refunds into a reconciled daily revenue product. This is a self-directed build brief; checklists record your work, not an automated certification.',level:'Foundation → Builder',steps:['Write the business definition of net revenue and declare the grain of every input/output.','Create synthetic fixtures with multiple lines, failed payment attempts, refunds, NULLs, and duplicate deliveries.','Build staging tables and an order-line fact with customer/product dimensions.','Implement daily revenue SQL and compare it against independently calculated fixture totals.','Add uniqueness, non-null, relationship, and reconciliation checks.','Document source-to-report lineage, a refresh objective, and a retry-safe load procedure.'],deliverable:'A repository with schema, synthetic data, transformations, executable tests, a metric definition, and a short explanation of the join-fanout trap.',source:sources.modeling},
  {id:'project-api',title:'A restartable API ingestion service',summary:'Build a Python client that can recover after a timeout without skipping or duplicating logical records. Use a mock API or a documented public dataset.',level:'Builder',steps:['Define pagination, rate-limit, mutation, and deletion assumptions for the source.','Build a mock endpoint or fixtures for normal pages, 429 responses, timeouts, empty pages, and repeated cursors.','Stream records in bounded batches and validate schema/units.','Persist output and checkpoint state with a replay-safe design.','Inject a crash after output commit but before checkpoint acknowledgement.','Demonstrate restart, deduplication, rejected-row policy, and useful redacted telemetry.'],deliverable:'An ingestion program, fault-injection tests, restart evidence, and a runbook covering permanent and transient failures.',source:sources.ingestion},
  {id:'project-stream',title:'A late-arriving transit event stream',summary:'Build or locally simulate passenger counts by event-time window, including disconnected sensors, repeated events, and late arrivals.',level:'Builder → Professional',steps:['Write latency and completeness requirements plus an explicit late-event policy.','Generate deterministic events with event time, arrival time, vehicle ID, and stable event ID.','Implement windowed counts and bounded duplicate handling using a chosen stream engine or a clearly labelled local simulator.','Inject an idle partition and out-of-order arrivals; inspect watermark behavior.','Test checkpoint/restart behavior and qualify the sink’s delivery guarantee.','Compare finalized and corrected results against an independent batch recomputation.'],deliverable:'A reproducible stream lab with event fixtures, timeline, correctness assertions, recovery demo, and a tradeoff explanation.',source:sources.streaming},
  {id:'project-lakehouse',title:'A lakehouse that survives change',summary:'Practice table evolution and maintenance on synthetic logistics data without losing historical query correctness.',level:'Professional',steps:['Choose a supported local engine/catalog/table-format combination and pin versions.','Load Parquet-backed data with a documented schema and partition strategy.','Exercise a supported column rename and add a nullable field; verify old and new records.','Change the partition specification and inspect the behavior of historical files.','Create small files, measure query/planning behavior, and compact using table-aware tooling.','Test snapshot queries, retention, and a recovery procedure before cleanup.'],deliverable:'Scripts, versioned environment instructions, before/after measurements, evolution tests, and a maintenance runbook.',source:sources.lakehouse},
  {id:'project-incident',title:'On-call for the morning finance report',summary:'Design a small pipeline, deliberately break it, then restore a trustworthy report under a defined deadline.',level:'Professional',steps:['Define a measurable freshness/completeness objective and identify the report’s consumers.','Instrument source arrival, accepted/rejected counts, partition completion, and lineage.','Inject three failures: missing input, duplicate retry, and semantic unit change.','Write alerts with scope, owner, and a concrete runbook action.','Practice a scoped repair or rollback and reconcile the output before publication.','Write a blameless postmortem with timeline, impact, contributors, and verifiable prevention actions.'],deliverable:'An incident packet containing synthetic logs, dashboards or metric queries, a runbook, repair evidence, and a postmortem.',source:sources.reliability},
  {id:'project-rag',title:'A tutor that can show its evidence',summary:'Build a small retrieval-assisted documentation tutor with engine-aware sources and a deterministic SQL checker. Keep the generated explanation separate from the verdict.',level:'Professional',steps:['Curate a small permitted set of official SQL documents and record source URL, engine, version, retrieval time, and license/access policy.','Chunk by semantic sections and index text with lexical search first; add embeddings only after a baseline evaluation.','Retrieve with engine/version filters and return citations with every supported technical claim.','Execute SQL in an isolated, resource-bounded sandbox and pass result differences to the tutor as evidence.','Create evals for correct retrieval, wrong-engine documents, stale sources, no evidence, prompt injection in retrieved text, and incorrect SQL.','Keep provider secrets server-side and test authorization, rate limits, source deletion, and abstention.'],deliverable:'A small working tutor, source manifest, evaluation set and results, threat model, and explicit limitations.',source:'https://arxiv.org/abs/2005.11401'},
  {id:'project-cost',title:'Make an expensive query explainable',summary:'Optimize a reproducible analytical workload while proving that its answer and freshness stay correct.',level:'Builder → Professional',steps:['Choose a local dataset or a cost-controlled cloud sandbox; record the engine and version.','Create a baseline query and independently verify its output.','Capture plan, scanned data, runtime, and resource/cost evidence where available.','Evaluate projection, pruning, pre-aggregation, join strategy, and materialization one change at a time.','Test skewed keys, NULLs, and realistic data volume; compare every result with the baseline.','Write a decision record including gains, maintenance cost, freshness tradeoffs, and cases where the optimization does not help.'],deliverable:'A benchmark report with reproducible SQL, fixtures, actual measurements, correctness checks, and an optimization decision record.',source:sources.warehouse},
  {id:'project-features',title:'Point-in-time features without leakage',summary:'Create a reproducible training dataset for a synthetic payment-risk task, preserving what was knowable at each decision.',level:'Professional',steps:['Define event time, feature availability time, label availability, and the prediction moment.','Generate synthetic payments, account changes, late corrections, and delayed chargeback labels.','Build point-in-time joins and prove future information cannot enter predictors.','Use a realistic temporal split and retain dataset/code versions.','Compare batch and serving feature definitions on boundary and timezone fixtures.','Add checks for missingness, distribution shifts, stale features, and reproducibility.'],deliverable:'Feature-building code, temporal fixtures, leakage tests, versioned dataset metadata, and a concise training-serving contract.',source:sources.mlops},
];
